INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('compound_part_of', 'etymological', 'has_compound_part', FALSE, FALSE, 'Documented compound component relation in STEP lexicon.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('derived_from_root', 'etymological', 'root_has_derivative', FALSE, FALSE, 'Documented etymological or morphological derivation from a lexical root; never implies synonymy.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('explicit_source_word_alignment', 'lexical', NULL, FALSE, FALSE, 'Explicit source-provided original-language word alignment (e.g. MACULA Hebrew to Septuagint Greek token tag).') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('greek_transliteration_of', 'etymological', 'transliterated_into_greek', FALSE, FALSE, 'Documented STEP Greek loanword or proper-name transliteration of a Semitic entry.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('has_lexical_sense', 'lexical', 'sense_of_lemma', FALSE, FALSE, 'Links a canonical lemma to one of its documented lexical senses.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('hebrew_cognate_of', 'etymological', 'aramaic_cognate_of', FALSE, FALSE, 'Documented STEP Hebrew-to-Aramaic cognate relationship; never implies synonymy.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('homograph_subdivision', 'lexical', 'homograph_subdivision', TRUE, FALSE, 'Explicit separation of numbered homographs sharing an unpointed or base Strong''s code.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('identified_as_in_passage', 'textual_parallel', 'identifies_symbol', FALSE, FALSE, 'Explicit intra-textual identification stated within a biblical passage (e.g., Rev 1:20).') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('lexeme_realizes_lemma', 'lexical', 'has_lexeme_entry', FALSE, FALSE, 'Links a lexicon entry (TBESH/TBESG) to its canonical headword lemma.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('lexical_distinction', 'lexical', 'lexical_distinction', TRUE, FALSE, 'Explicit distinction preventing conflation of distinct lexemes or homographs.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('lexicon_translation_equivalent', 'lexical', NULL, FALSE, FALSE, 'Lexicon-documented cross-language translation equivalent without token-level alignment claim.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('narrative_parallel', 'interpretive', 'narrative_parallel', TRUE, FALSE, 'Reviewed literary type-scene or narrative parallel with explicit scope and controls.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('parallel_passage_text', 'textual_parallel', 'parallel_passage_text', TRUE, FALSE, 'Audited textual parallel across biblical books (e.g., Psalm 18 and 2 Samuel 22).') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('possible_allusion', 'interpretive', 'alluded_to_by', FALSE, FALSE, 'Reviewed intertextual allusion with explicit textual span evidence.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('source_provided_lexical_equivalent', 'lexical', NULL, FALSE, FALSE, 'Source-provided lexical dictionary equivalent from dataset annotations (origin unverified as manuscript alignment).') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('spelling_or_form_variant_of', 'lexical', 'has_spelling_or_form_variant', FALSE, FALSE, 'Documented orthographic spelling or stem variant in STEP lexicon.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('verse_parallel_cooccurrence', 'textual_parallel', NULL, TRUE, FALSE, 'Words co-occurring in corresponding Hebrew and Greek verses without claiming token-level correspondence.') ON CONFLICT DO NOTHING;
INSERT INTO public.relation_types ("relation_type", "category", "inverse_relation_type", "is_symmetric", "implies_synonymy", "description") VALUES ('versification_equivalent', 'versification', 'versification_equivalent', TRUE, FALSE, 'Documented passage numbering shift across Masoretic, English, or KJV/TR versification schemes.') ON CONFLICT DO NOTHING;
