INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14257, 'G1510', 'grc', 'G1510', 'G1510', 'G1510 =', 'G1510', 'εἰμί', 'eimi', 'G:V', 'to be', 'εἰμί , with various uses and significations, like the English verb to be . __I. As substantive verb. __1. Of persons and things, to be, exist : Act.17:28 , Jhn.1:1, 8:58, 17:5 , al; ὁ ὢν καὶ ὁ ἦν (for past ptcp.), Rev.1:4, 8, 4:8, 11:17, 16:5 (see Swete, Ap. , 5; M, Pr. , 228); τὰ (μὴ) ὄντα, Rom.4:17 , 1Co.1:28 . __2. Of times, events, etc., to be, happen, take place : Mat.24:3 , Mrk.14:2, 15:42 , Luk.21:23 , Jhn.4:6, 23, 5:10 , al. __3. to be present, be in a place, have come : Mat.2:13, 15 , M', 1, 3685, 4, 'TBESG:G1510') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14261, 'G1514', 'grc', 'G1514', 'G1514', 'G1514 =', 'G1514', 'εἰρηνεύω', 'eirēneuō', 'G:V', 'be at peace', 'εἰρηνεύω (εἰρήνη), [in LXX chiefly for שׁלם, שׁקט ;] __1. to bring to peace, reconcile (so 1Ma.6:60 ). __2. to keep peace, be at peace : Mrk.9:50 , Rom.12:18 , 2Co.13:11 , 1Th.5:13 (cf. Sir.28:9; Cremer, 246). † (AS)', 1, 3689, 4, 'TBESG:G1514') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14266, 'G1519', 'grc', 'G1519', 'G1519', 'G1519 =', 'G1519', 'εἰς', 'eis', 'G:PREP', 'toward', 'εἰς , prep. with accusative, expressing entrance, direction, limit, into, unto, to, upon, towards, for, among (Lat. in, with accusative). __I. Of place. __1. After verbs of motion; __(a) of entrance into : Mat.8:23, 9:7 , Mrk.1:45 , Luk.2:15, 8:31 , al.; __(b) of approach, to or towards : Mrk.11:1 , Luk.6:8, 19:28 , Jhn.11:31, 21:6 , al.; __(with) before pl. and collective nouns, among : Mrk.4:7, 8:19, 20 , Luk.11:49 , Jhn.21:23 , al.; __(d) Of a limit reached, unto, on, upon : Mat.8:18, 21:1 , ', 1, 3695, 4, 'TBESG:G1519') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14267, 'G1520', 'grc', 'G1520', 'G1520', 'G1520 =', 'G1520', 'εἷς', 'ehis', 'G:A-NUI', 'one', 'εἷς ιά, ἕν, genitive ἑνός, μιᾶς, ἑνός, cardinal numeral, one ; __1. one , as opposite to many: Mat.25:15 , Rom.5:12 , 1Co.10:8 , al.; as subst., Rom.5:15 , Eph.2:14 ; id. with genitive partit., Mat.5:19 , al.; before ἐκ (ἐξ), Mrk.14:18 , Jhn.6:8 , al.; metaphorically, of union and concord, Jhn.10:30 17:11 , Rom.12:4-5 , Php.1:27 ; ἀπὸ μιᾶς (B1., § 44, 1), Luk.14:18; with neg., εἷς. . . οὐ (μή), more emphatic than οὐδείς, no one, none (cl.), Mat.5:18 10:29 , Luk.11:46 12:6 . __2. Emphatically, to', 1, 3696, 4, 'TBESG:G1520') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14284, 'G1537', 'grc', 'G1537', 'G1537', 'G1537 =', 'G1537', 'ἐκ', 'ek', 'G:PREP', 'out from', 'ἐκ (ἐξ), prep. with genitive, from out of, from ( see Addendum, p. 492). This entry is included here, but in the print version the entry is found on p. 492. ἐκ , before a vowel ἐξ, prep. with genitive, of motion outwards, separation from (opposite to εἰς; = Lat. e, ex), from out of, from among, from . __I. Of Place, __1. of motion, out of, forth from, off from : Jhn.6:31 , Act.9:3 , Gal.1:8 , al.; esp. after verbs of motion, Mat.8:28 17:9 , Mrk.1:25 7:28 , Jhn.1:33 20:1 , Act.12:7, 17 27:30 , al', 1, 3715, 4, 'TBESG:G1537') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14285, 'G1538', 'grc', 'G1538', 'G1538', 'G1538 =', 'G1538', 'ἕκαστος', 'hekastos', 'G:A', 'each', '1. every, every one, each, each one , Lat. quisque , (Homer), etc.; the singular is often joined with a pl. Verb, ἔβαν οἴκονδε ἕκαστος they went home every one of them , (Iliad by Homer); ἕκαστος ἐπίστασθε (Xenophon Historicus):—;the singular is also put in apposition with a pl. Noun, Τρῶας ἕκαστον ὑπήλυθε τρόμος (for Τρώων ἕκαστον)) fear seized them every one , (Iliad by Homer) 2. in plural all and each one , (Homer) 3. more definitely, εἷς ἕκαστος, Lat. unusquisque , every single one, (Herdotu', 1, 3716, 4, 'TBESG:G1538') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14324, 'G1577', 'grc', 'G1577', 'G1577', 'G1577 =', 'G1577', 'ἐκκλησία', 'ekklēsia', 'G:N-F', 'assembly', 'ἐκκλησία , -ας, ἡ (ἐκ-καλέω), [in LXX chiefly for קָהָל, otherwise for one of its cogn. forms ;] __1. prop., an assembly of citizens regularly convened (in Thuc., ii, 22, opposite to σύλλογος, a concourse ): Act.19:32, 39 41 . __2. In LXX of the assembly, congregation, community of Israel ( Deu.4:10 23:2 , al.): Act.7:38 , Heb.2:12 " (LXX) . __3. NT, esp. of an assembly or company of Christians, a (the) church ; __(a) of gatherings for worship : 1Co.11:18 14:19, 34 35 ; __(b) of local communitie', 1, 3758, 4, 'TBESG:G1577') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14354, 'G1607', 'grc', 'G1607', 'G1607', 'G1607 =', 'G1607', 'ἐκπορεύω', 'ekporeuō', 'G:V', 'to depart', 'ἐκ-πορεύω [in LXX chiefly for יָצָא ;] to make to go out ; pass. and mid., to go forth : Luk.3:7 , Act.25:4 ; of demons leaving one possessed, Mat.17:21 (WH om.), Act.19:12; of excrement, Mk 719; before ἀπό, Mat.20:29 , Mrk.10:46 ; ἐκ, Mrk.13:1 (of the dead rising, Jhn.5:29 ); ἐκεῖθεν, Mrk.6:11; ἔξω, Mrk.11:19; είς, Mrk.10:17 , Jhn.5:29 ; ἐπί, with accusative of person(s), Rev.16:14; πρός, with accusative of person(s), Mat.3:5 , Mrk.1:5 ; εἰσπορ- (which see) καὶ ἐ., Act.9:28; metaphorically, to ', 1, 3789, 4, 'TBESG:G1607') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14383, 'G1636', 'grc', 'G1636', 'G1636', 'G1636 =', 'G1636', 'ἐλαία', 'elaia', 'G:N-F', 'olive tree', 'ἐλαία (Attic, ἐλάα), -ας, ἡ [in LXX for זַיִת ;] __1. an olive tree : Rom.11:17, 24 , Rev.11:4 ; τ. ὄρος τῶν ἐ. (זַיִת הַר, Zec.14:4 ), the Mount of Olives: Mat.21:1 24:3 26:30 , Mrk.11:1 13:3 14:26 , Luk.19:37 22:39 ; τὸ καλούμενον ἐ. (T, ἐλαιών, which see), Luk.19:29 21:37 . __2. an olive (Aristoph.): Jas.3:12. † (AS)', 1, 3821, 4, 'TBESG:G1636') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14470, 'G1722', 'grc', 'G1722', 'G1722', 'G1722 =', 'G1722', 'ἐν', 'en', 'G:PREP', 'in/on/among', 'ἐν , prep , (the most frequently of all in NT), with dative (= Heb. בְּ, Lat. in, with abl.). __I. Of place, with dative of thing(s), of person(s), in, within, on, at, by, among : ἐν τ. πόλει, Luk.7:37; τ. οφθαλμῷ, Mat.7:3; τ. κοιλίᾳ, Mat.12:40; τ. ὄρει, 2Pe.1:18; τ. θρόνῳ, Rev.3:21; τ. δεξιᾷ τ. θεοῦ, Rom.8:34; ἐν ἡμῖν Abbott-Smith has ὑμῖν. , Luk.1:1; of books, ἐν τ. βιβλίῳ, Gal.3:10; τ. νόμῳ, Mat.12:5 , al.; ἐν τοῖς τ. Πατρός, in my Father''s house (RV; cf. M, Pr. , 103), Luk.2:49; trop., of th', 1, 3915, 4, 'TBESG:G1722') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14547, 'G1799', 'grc', 'G1799', 'G1799', 'G1799 =', 'G1799', 'ἐνώπιον', 'enōpion', 'G:PREP', 'before', 'ἐνώπιος , -ον (ὤψ), [in LXX for פָּנִים, etc. ;] face to face, in sight (Theocr.; ἄρτοι ἐ., Exo.25:29 ): neut., ἐνώπιον, in vernacular, with force of prep. with genitive [in LXX for פָּנִים, עַיִן, etc., cf. Dalman, Words , 31 f., 209 f., and Deiss., BS., 213], in NT, most frequently in Lk, Ac, Re, never in Mt, Mk, before, in the presence of : Luk.1:19 Luk.4:7 , Act.4:10 Act.6:5 , Rev.1:4 2:14 , al.; esp. ἐ. Κυρίου (θεοῦ), in the sight of God, or with God as witness or as judge, Rom.14:22 , 1Co.', 1, 3997, 4, 'TBESG:G1799') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14602, 'G1854', 'grc', 'G1854', 'G1854', 'G1854 =', 'G1854', 'ἔξω', 'exō', 'G:PREP', 'out/outside(r)', 'ἔξω adv. (ἐξ), [in LXX for חוּץ ;] __1. outside, without ; __(a) adverbially : Mat.12:46 , Mrk.3:31 11:4 , Luk.8:20 , Jhn.18:16 , al.; with art., ὁ ἔ., he who is without; metaphorically, in pl., οἱ ἔ., of those outside the Church, 1Co.5:12-13 , Col.4:5 (Lft., in l), 1Th.4:12; ὁ ἔ. ἄνθρωπος, 2Co.4:16; αἱ ἔ. πόλεις, Act.26:11; __(b) as prep. with genitive: Luk.13:33 , Act.21:5 , Heb.13:11-12 __2. After verbs of motion; __(a) adverbially, forth, out : Mat.5:13 Mrk.14:68 , Luk.22:62 , Jhn.19:4, 13 ,', 1, 4054, 4, 'TBESG:G1854') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14657, 'G1909', 'grc', 'G1909', 'G1909', 'G1909 =', 'G1909', 'ἐπί', 'epi', 'G:PREP', 'upon/to/against', 'ἐπί (before a smooth breathing ἐπ᾽, before a rough breathing ἐφ᾽), prep. with genitive, dative, accusative (accusative most frequently in NT), with primary sense of superposition, on, upon . __I. C. genitive, __1. of place, answering the question, where? __(a) of the place on which, on, upon : ἐπὶ (τ.) γῆς, Mat.6:10, 19 , al.; τ. κεφαλῆς, 1Co.11:10; τ. νεφελῶν, Mat.24:3 o, al.; like ἐν, in constr. praegn. after verbs of motion: βάλλειν, Mrk.4:26; σπείρειν, ib. 31; ἔρχεσθαι, Heb.6:7 , al.; figura', 1, 4112, 4, 'TBESG:G1909') ON CONFLICT DO NOTHING;
