INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14941, 'G2192', 'grc', 'G2192', 'G2192', 'G2192 =', 'G2192', 'ἔχω', 'echō', 'G:V', 'to have/be', 'ἔχω , [in LXX for אָצֵל (ἐχόμενος), יֵשׁ,בַּעַל, etc., 59 words in all ;] (on the Aktionsart of the various tenses, see M, Pr. , 110, 145, 150, 183), to have , as in cl., in various senses and constructions. __I. Trans.; __1. 1. to have, hold, hold fast , etc.; __(a) to hold , as, in the hand : Rev.5:8 14:6 , al.; ἐν τ. χειρί, Rev.1:16 10:2 , al.; __(b) of arms and clothing, = φέρω, φορέω, to bear, wear : Mat.3:4 22:12 , al.; so frequently present ptcp. (LS, see word, A, I, 6; Bl., 74, 2), Mrk.1', 1, 4412, 4, 'TBESG:G2192') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14974, 'G2222', 'grc', 'G2222', 'G2222', 'G2222 =', 'G2222', 'ζωή', 'zōē', 'G:N-F', 'life', 'ζωή , -ῆς, ἡ (ζάω), [in LXX chiefly for חַיִּים ;] life (in Hom., Hdt., = βίος, which see; later, existence, vita quâ vivimus , as distinct from βίος, vita quam vivimus ; opposite to θάνατος); __1. of natural life : Luk.16:25 , Act.8:33 , 1Co.15:19 , 1Ti.4:8 , Heb.7:3 , Jas.4:14 ; πνεῦμα ζωῆς, Rev.11:11; ψυχὴ ζωῆς ( Gen.1:30 ), Rev.16:3 ; of the life of one risen from the dead, Rom.5:10 , Heb.7:16 . __2. Of the life of the kingdom of God, the present life of grace and the life of glory which is ', 1, 4448, 4, 'TBESG:G2222') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14978, 'G2226', 'grc', 'G2226', 'G2226', 'G2226 =', 'G2226', 'ζῷον', 'zōon', 'G:N-N', 'living thing', 'ζῷον (Rec. ζῶον, see LS, see word), -ου, τό (ζωός, alive), [in LXX for חַי (chiefly) and cognate forms; frequently in Wis ;] a living creature, an animal : Rev.4:6-9 5:6 ff. Rev.6:1 ff. Rev.7:11 14:3 15:7 19:4 ; ζῴων τ. αἷμα, Heb.13:11; ἄλογα ζ., 2Pe.2:12 , Ju 10 .† SYN. : θηρίον, in which the brutal, bestial element is emphasized, and which is never used of sacrificial animals. On the other hand, ζ. is the more comprehensive, as expressing the vital element common to the whole anima] creation (', 1, 4452, 4, 'TBESG:G2226') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14979, 'G2227', 'grc', 'G2227', 'G2227', 'G2227 =', 'G2227', 'ζωοποιέω', 'zōopoieō', 'G:V', 'to make alive', 'ζωο-ποιέω , ῶ [in LXX for חָיָה pi., hi., Jdg.21:14 , 4Ki.5:7 , Neh.9:6 , Job.36:6 , Psa.70:20 , Ecc.7:12 * ;] __1. in cl. (= ζωογονέω), to produce alive. __2. In LXX and NT, to make alive, cause to live, quicken ( DCG , ii, 606a; Cremer, 275): Jhn.5:21 6:53 , Rom.4:17 8:11 , 1Co.15:45 , 2Co.3:6 , Gal.3:21 . Pass., 1Co.15:22 15:36 , 1Pe.3:18 .† (AS)', 1, 4453, 4, 'TBESG:G2227') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15072, 'G2316', 'grc', 'G2316', 'G2316', 'G2316 =', 'G2316', 'θεός', 'theos', 'G:N-M/F', 'God', 'θεός , -οῦ, ὁ, ἡ ( Act.19:37 only; see M, Pr. , 60, 244), late voc., θεέ ( Mat.27:46; cf. Deu.3:24 , al.), [in LXX chiefly for אֱלֹהִים, also for אֵל and other cognate forms, יהוה, etc. ;] a god or deity, God . __1. In polytheistic sense, a god or deity : Act.28:6 , 1Co.8:4 , 2Th.2:4 , al.; pl., Ac. 14:11 19:26 , Gal.4:8 , al. __2. Of the one true God ; __(a) anarthrous : Mat.6:24 , Luk.20:38 , al.; esp. with prep. (Kühner 3, iii, 605), ἀπὸ θ., Jhn.3:2; ἐκ, Act.5:39 , 2Co.5:1 , Php.3:9 ; ὑπό, Ro', 1, 4551, 4, 'TBESG:G2316') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15118, 'G2362', 'grc', 'G2362', 'G2362', 'G2362 =', 'G2362', 'θρόνος', 'thronos', 'G:N-M', 'throne', 'θρόνος , -ου, ὁ [in LXX chiefly for כִּסֵּא, Exo.11:5 , al. ;] in Hom., a seat, chair. Later, a throne, chair of state, seat of authority; of kings: metaphorically, of God, Mat.5:34 , Act.7:49 " (LXX), Rev.1:4 , al.; by meton., for kingly power, sovereignty, Luk.1:32, 52 , Act.2:30 ; for an angelic hierarchy, Col.1:16; of Christ, Mat.19:28 , Rev.3:21 , al.; of Satan, Rev.2:13; τ. θηρίου, Rev.16:10; of the Apostles, Mat.19:28 , Luk.22:30 , cf. Rev.20:4; of πρεσβύτεροι, Rev.4:4 11:16 (on θ. τῆς χά', 1, 4601, 4, 'TBESG:G2362') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15249, 'G2476', 'grc', 'G2476', 'G2476', 'G2476 =', 'G2476', 'ἵστημι', 'histēmi', 'G:V', 'to stand', 'ἵστημι , and in late writers, also ἱστάνω (Veitch, see word; Bl., §23, 2; M, Pr. , 55), [in LXX chiefly for עמד, קוּם, also for נצב ni., hi., יצב hith., etc.]. __I. Trans, in pres., impf., fut. and 1 aor. act. and in the tenses of the pass. __1. to make to stand, to place, set, set up, establish, appoint : with accusative of person(s), Mrk.7:9 , Act.1:23 6:13 17:31 , Heb.10:9 ; id. before ἐπί, with accusative loc, Mat.4:5 , Luk.4:9 ; ἐν μέσῳ, Mat.18:2 , Mrk.9:36 , Jhn.8:[3]; ἐνώπιον, Act.6:6; πα', 1, 4740, 4, 'TBESG:G2476') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15253, 'G2480', 'grc', 'G2480', 'G2480', 'G2480 =', 'G2480', 'ἰσχύω', 'ischuō', 'G:V', 'be strong', 'ἰσχύω (ἰσχύς), [in LXX for חָזַק, גִּבּוֹר, עָצַם, etc. ;] __1. to be strong in body : Mat.9:12 , Mrk.2:17 . __2. to be powerful, have power, prevail : Act.19:20 , Rev.12:8 ; before κατά, with genitive of person(s), Act.19:16; with inf., to be able (MM, Exp. , xv): Mat.8:28 26:40 , Mrk.5:4 9:18 (inf. understood) Mrk.14:37 , Luk.6:48 8:43 13:24 14:6, 29-30 16:3 20:26 , Jhn.21:6 , Act.6:10 15:10 25:7 27:16 ; with accusative, Php.4:13 , Jas.5:16 ; of things, to avail, be serviceable (MM, Exp. , l.w', 1, 4745, 4, 'TBESG:G2480') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15320, 'G2532', 'grc', 'G2532', 'G2532', 'G2532 =', 'G2532', 'καί', 'kai', 'G:CONJ', 'and', 'καί , conj. , and __I. Copulative. __1. Connecting single words; __(a) in general : Mat.2:18, 16:1 , Mrk.2:15 , Luk.8:15 , Heb.1:1 , al. mult.; repeated before each of the terms in a series, Mat.23:23 , Luk.14:21 , Rom.7:12, 9:4 , al. __(b) connecting numerals (WM, §37, 4): Jhn.2:20 , Act.13:20 ; __(with) joining terms which are not mutually exclusive, as the part with the whole : Mat.8:33, 26:59 , Mrk.16:17 , Act.5:29 , al. __2. Connecting clauses and sentences : Mat.3:12 , Act.5:21 , al. mult.', 1, 4819, 4, 'TBESG:G2532') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15339, 'G2545', 'grc', 'G2545', 'G2545', 'G2545 =', 'G2545', 'καίω', 'kaiō', 'G:V', 'to kindle/burn', 'καίω [in LXX for בָּעַר, יָקַד, שָׂרַף, etc. ;] __1. to kindle, light : with accusative, λύχνον, Mat.5:15; pass., to be lighted, to burn : ptcp., Luk.12:35 , Rev.4:5 8:10 19:20 ; πυρί Heb.12:18 , Rev.8:8 21:8 ; metaphorically, Luk.24:32 , Jhn.5:35 . __2. to burn, destroy by fire : pass., Jhn.15:6 , 1Co.13:3 .† (AS)', 1, 4839, 4, 'TBESG:G2545') ON CONFLICT DO NOTHING;
INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15366, 'G2570G', 'grc', 'G2570', 'G2570G', 'G2570G =', 'G2570G', 'καλός', 'kalos', 'G:A', 'good', 'καλός , -ή, -όν, [in LXX chiefly for טוֹבָה ,טוֹב, also for יָפֶה, etc. ;] __1. primarily, of outward form ("related to . . . ἀγαθός as the appearance to the essence," Cremer, 339), fair, beautiful : λίθοι (BV, goodly ), Luk.21:5. __2. In reference to use, of that which is well adapted to its ends, good, excellent : of fish, τ. καλά (opposite to σαπρά), Mat.13:48; σπέρμα, Mat.13:24, 27, 37, 38 ; καρπός, Mat.3:10 7:17-19 12:33 , Luk.3:9 [WH] 6:43; δένδρον (opposite to σαρπόν), Mat.12:33 , Luk.6:4', 1, 4864, 4, 'TBESG:G2570G') ON CONFLICT DO NOTHING;
