INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15809, 'G3004G', 'grc', 'G3004', 'G3004G', 'G3004G =', 'G3004G', 'λέγω', 'legō', 'G:V', 'to say', 'λέγω , [in LXX very freq., chiefly for אמר; λέγει for נְאֻם, Gen.22:16 , al. ;] __1. in Hom., to pick out, gather, reckon, recount . __2. In Hdt. and Att., to say, speak, affirm, declare : absol., Act.13:15, 24:10 ; before orat. dir., Mat.9:34 , Mrk.3:11 , Jhn.1:29 , al.; before ὅτι recit., Mrk.3:21 , Luk.1:24 , Jhn.6:14 , al.; accusative and inf., Luk.11:18 , Jhn.12:29 , al.; after another verb of speaking, προσφωνεῖν κ. λέγειν, Mat.11:17 , al.; ἀπεκρίθη (ἐλάλησεν) λέγων (καὶ λέγει; Dalman, Wor', 1, 5329, 4, 'TBESG:G3004G') ON CONFLICT DO NOTHING;
