INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16829, 'G4098', 'grc', 'G4098', 'G4098', 'G4098 =', 'G4098', 'πίπτω', 'piptō', 'G:V', 'to collapse', 'πίπτω [in LXX chiefly for נָפַל ;] to fall ; __1. of descent, to fall, fall down or from : before ἐπί, with accusative loc., Mat.10:29 , al.; εἰς, Mat.15:14 , al.; ἐς μέσῳ, with genitive, Luk.8:7; παρὰ τ. ὁδόν, Mat.13:4 , Mrk.4:4 , Luk.8:5 ; before ἀπό, Mat.15:27 , al.; ἐκ, Mrk.13:25 , Luk.10:18 , Rev.8:10 9:1 . Metaphorical: ὁ ἥλιος, before ἐπί, Rev.7:16; ἀχλὺς κ. σκότος, Act.13:11; ὁ κλῆρος, Act.1:26; ὑπὸ κρίσιν, Jas.5:12. __2. Of prostration, __(a) of persons, to fall prostrate, prostrate one', 1, 6395, 4, 'TBESG:G4098') ON CONFLICT DO NOTHING;
