INSERT INTO public.lexemes ("id", "lexeme_key", "language", "base_strongs", "extended_strongs", "disambiguated_strongs", "unified_strongs", "original_lemma", "transliteration", "pos", "primary_gloss", "homograph_note", "source_release_id", "lemma_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (17374, 'G4621', 'grc', 'G4621', 'G4621', 'G4621 =', 'G4621', 'σῖτος', 'sitos', 'G:N-M', 'grain', 'σῖτος , -ου, ὁ [in LXX chiefly for דָּגָן ;] wheat, corn : Mat.3:12 13:25, 29-30 Mrk.4:28 , Luk.3:17 12:18 16:7 22:32 , Jhn.12:24 , Act.27:38 , 1Co.15:37 , Rev.6:6 18:13 .† σιτίοι, -ου, τό (dimin. of σῖτος), [in LXX: Pro.30:22 (לֶחֶם)* ;] __1. corn, grain : Act.7:12 (but see 131., § 9, 1). __2. Mostly in pl., σιτία, bread, food, provisions (LXX, l.with, Hdt., al.).† (AS)', 1, 6970, 4, 'TBESG:G4621') ON CONFLICT DO NOTHING;
