INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11211, 'sense:G2985:primary', 43, 7, NULL, 'primary', 1, 'lamp / torch', 'Used in Rev 4:5 ("seven torches/lamps of fire burning before the throne").', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2985') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11212, 'sense:G3087:primary', 45, 6, NULL, 'primary', 1, 'lampstand', 'Stand holding lamps (Rev 1:12, 1:20, 11:4); distinct from G2985 (lampas, torch/lamp).', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3087') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11213, 'sense:G4151:primary', 46, 8, NULL, 'primary', 1, 'spirit / Spirit', 'Used in Rev 1:4, 3:1, 4:5, 5:6 ("the seven spirits of God").', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4151G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11244, 'sense:G0032G:primary', 2101, 12731, NULL, 'primary', 1, 'angel', 'ἄγγελος , -ου, ὁ, [in LXX chiefly for מַלְאָךְ ;] __1. a messenger , one sent : Mat.11:10 , Jas.22:25 . __2. As in LXX, in the special sense of angel , a spiritual, heavenly being, attendant upon God and employed as his messenger to men, to make known his purposes, as Luk.1:11 , or to execute them, as Mat.4:6. The ἄ. in Rev.1:20-2:1 , al., is variously understood as __(1) a messenger or delegate, __(2) a bishop or ruler, __(3) a guardian angel, __(4) the prevailing spirit of each church, i.e. th', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0032G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11305, 'sense:G0233:primary', 2317, 12942, NULL, 'primary', 1, 'to salt', 'ἁλίζω (ἅλς), [in LXX for מָלַח ;] to salt, season with salt : Mat.5:13 , Mrk.9:49 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0233') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11415, 'sense:G0191:primary', 2269, 12897, NULL, 'primary', 1, 'to hear', 'ἀκούω , [in LXX chiefly for שׁמע ] to hear, listen, attend, perceive by hearing, comprehend by hearing . __1. Intrans.: Mrk.4:3 7:37 , Jas.2:5 , Rev.2:7 , al.; τ. ὠσίν, Mat.13:15 (LXX); with cogn. dative, ακοῇ ἀ. (see: ἀκοή), Mat.13:14 , Act.28:26 " (LXX) ; ὁ ἔχων ὦτα (οὖς) ἀκούειν, ἀκουσάτω, Mat.11:15 , Mrk.4:23 , Rev.2:7 , al. __2. Trans., prop. with accusative of thing(s), of thing heard, genitive of person(s), from whom heard (LS, see word): Act.1:4; with accusative of thing(s), Mat.12:19 , ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0191') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11421, 'sense:G0217:primary', 2296, 12923, NULL, 'primary', 1, 'salt', 'ἅλας (T, ἅλα), -ατος, τό, late form of cl. ἅλς, -ος, ὁ (MM, VGT , see word), [in LXX chiefly for מְלַח ;] salt , lit, and figuratively: Mat.5:13 , Mrk.9:50 Luk.14:34 ; like cl. ἅλες, wit , of wisdom and grace in speech: Col.4:6. † (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0217') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11468, 'sense:G0240:primary', 2324, 12949, NULL, 'primary', 1, 'one another', 'ἀλλήλων (genitive pl.), dative -οις, -αις, accusative -ους, -ας, -α (no nom.), recipr. pron. (ἄλλος), of one another, mutually : Mat.25:32 , Mrk.4:41 , Jhn.13:22 , al. (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0240') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11514, 'sense:G0281:primary', 2371, 12991, NULL, 'primary', 1, 'amen', 'ἀμήν , indecl. (Heb. אָמֵן, verbal adj. fr. אמן, to prop. ni., be firm ), [in LXX: 1Ch.16:36 , I Est.9:46 , Neh.5:13 8:6 , Tob.8:8 14:15 , 3Ma.7:23 , 4Ma.18:24 (elsewhere ''''א is rendered ἀληθινός, Isa.65:16; ἀληθῶς, Je 35 (28):6 ; γένοιτο, Num.5:22 , Deu.27:15 ff., 3Ki.1:36 , Psa.40 (41):13 71 (72):19 105 (106):48, Jer.11:5 )*.] __1. As adj. (cf. Is, l.with), ὁ ἀ., Rev.3:14. __2. As adv. , __(a) in solemn assent to the statements or prayers of another (Nu, Ne, etc., ll. with): ὁ ἀ., 1Co.14:16; _', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0281') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11594, 'sense:G0358:primary', 2451, 13069, NULL, 'primary', 1, 'unsalty', 'ἄναλος , -ον (ἅλς), [in Aq.: Eze.13:10-11, 15 22:28 * ;] saltless, insipid : Mrk.9:50. † (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0358') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11689, 'sense:G0444:primary', 2543, 13158, NULL, 'primary', 1, 'a human', 'ἄνθρωπος , -ου, ὁ, [in LXX chiefly for אִישׁ ,אָדָם, also for אֱנוֹשׁ, etc. ;] man : __1. generically, a human being, male or female (Lat. homo): Jhn.16:21; with art., Mat.4:4 12:35 , Mrk.2:27 , Jhn.2:25 , Rom.7:1 , al; disting. from God, Mat.19:6 , Jhn.10:33 , Col.3:23 , al.; from animals, etc., Mat.4:19 , Luk.5:10 , Rev.9:4 , al.; implying human frailty and imperfection, 1Co.3:4; σοφία ἀνθρώπων, 1Co.2:5; ἀνθρώπων ἐπιθυμίαι, 1Pe.4:2; κατὰ ἄνθρωπον περιπατεῖν, 1Co.3:3; κατὰ ἄ. λέγειν (λαλεῖν), R', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0444') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11854, 'sense:G0599:primary', 2709, 13314, NULL, 'primary', 1, 'to die', 'ἀπο-θνῄσκω , [in LXX chiefly for מוּת ;] to die : of natural death, Mrk.5:35 , al.; of violent death (pass. of ἀποκτείνω), esp. of Christ, Mat.26:35 , Jhn.12:33 , Heb.10:28 , al.; of spiritual death, Jhn.6:50 , Rom.8:13 , al.; with dative ref., Rom.6:2, 10 14:7, 8 , Gal.2:19 ; accusative, ὅ, Rom.6:10; before ἐν, Mat.8:32 , Jhn.8:21, 24 1Co.15:22 , Heb.11:37 , Rev.14:13 ; before ὑπέρ, περί, Jhn.11:50, 51 18:14 , Rom.5:6-8 14:15 , 1Co.15:3 , 2Co.5:15 , 1Th.5:10 , 1Pe.3:18 ; ἀπό, Col.2:20; ἐκ, Rev.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0599') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11866, 'sense:G0611:primary', 2721, 13326, NULL, 'primary', 1, 'to answer', 'ἀποκρίνω , ἀποκρίνομαι , [in LXX chiefly for ענה ;] in cl., __1. to separate, distinguish . __2. to choose . Mid., to answer : Mat.27:12 , Mrk.14:61 , Luk.3:16 23:9 , Jhn.5:17, 19 Act.3:12 . In late Gk. the pass, also is used in this sense, and pass. forms are the more frequently in NT (M, Pr. , 39, 161; MM, see word); __(a) in general sense : absol., Mrk.12:34; with accusative of thing(s), Mat.22:46; with dative of person(s), Mat.12:38; before πρός, Act.25:16; __(b) Hebraistically __(i) like ענ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0611') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11908, 'sense:G0649:primary', 2762, 13365, NULL, 'primary', 1, 'to send', 'ἀπο-στέλλω , [in LXX very freq., almost always for שׁלח ;] prop., to send away, to dispatch on service; __1. to send with a commission, or on service; __(a) of persons : Christ, Mat.10:40; the apostles, 10:16; servants, Mrk.12:2; angels, 13:27; __(b) of things : ὄνος, Mat.21:3; τὸ δρέπανον, Mrk.4:29; τ. λόγον, Act.10:36; τ. ἐπαγγελίαν (i.e. the promised Holy Spirit), Luk.24:49 , Rec.; before εἰς, Mat.20:2 , Luk.11:49 , Jhn.3:17 ; ὀπίσω, Luk.19:14; ἔμπροσθεν, Jhn.3:28; πρὸ προσώπου, Mat.11:10; πρ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0649') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11961, 'sense:G0741:primary', 2815, 13457, NULL, 'primary', 1, 'to season', 'ἀρτύω [in Sm.: Sng.8:2 * ;] __1. to arrange, make ready (Hom.). __2. Of food (as in comic writers), to season (MM, see word): Mrk.9:50 , Luk.14:34 , Col.4:6 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0741') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (11986, 'sense:G0721:primary', 2840, 13437, NULL, 'primary', 1, 'lamb', 'ἀρνίον , -ου, τό (dimin. of ἀρήν; see MM, see word), [in LXX: Psa.114:4 , 6 (pl., צֹאן בֵּן), Jer.11:19 (כֶּבֶשׂ), Jer.50:45 (צָעִיר)* ;] a little lamb, a lamb : Jhn.21:15 , Rev.2:7 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0721') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12009, 'sense:G0740:primary', 2862, 13456, NULL, 'primary', 1, 'bread', 'ἄρτος , -ου, ὁ, [in LXX chiefly for לֶחֶם ;] bread, a loaf : Mat.4:3 , 4 Mrk.3:20 , al.; ἄρτοι τ. προθέσεως, bread of the setting forth , i.e. the shewbread. Metaphorical, ὁ ἄ. τ. θεοῦ, τ. ζωῆς, ref. to Christ, Jhn.6:33, 35 ; in general, food : Mat.6:11 , al.; ἄ. φαγεῖν (Heb. אֲכֹל לֶחֶם), to eat (MM, see word), Lu 14:1 , al. (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0740') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12061, 'sense:G0792:primary', 2917, 13511, NULL, 'primary', 1, 'star', 'ἀστήρ , -έρος, ὁ [in LXX chiefly for כּוֹכָב ;] a star : Mat.2:2, 7-10 :, Mrk.13:25 , 1Co.15:41 , Rev.6:13 8:10-12 9:1 12:1, 4 ; metaphorically, ὁ ἀ. ὁ πρωϊνός Rev.2:28 22:16 ; ἀ. πλαῆται, Ju 13 ; ἀ. ἑπτά, symbolizing the angels of the seven churches, Rev.1:16, 20 2:1 3:1 (cf. ἄστρον, and see DCG , ii, 674 f.; MM, see word).† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0792') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12065, 'sense:G0796:primary', 2921, 13515, NULL, 'primary', 1, 'lightning', 'ἀστραπή , -ῆς, ἡ [in LXX for בָּרָק ;] lightning : Mat.24:27 28:3 , Luk.10:18 17:24 ; pl., Rev.4:5 8:5 11:19 16:18 ; of a lamp, shining brightness, Luk.11:36. † (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0796') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12117, 'sense:G0846:primary', 2973, 13565, NULL, 'primary', 1, 'it/s/he', 'αὐτός , -ή, -ό, determinative pron. , in late Gk. much more frequently than in cl. (WM, 178f.; Jannaris, HGG , §1399). __1. Emphatic (so always in nom. exc. when preceded by the art., see infr., iii); __(1) self (ipse), expressing opposition, distinction, exclusion, etc., αὐ. ἐκχυθήσεται, Luk.5:37; αὐ. ἐγινώσκεν, Jhn.2:25; αὐ.ὑμεῖς, Jhn.3:28; καὶ αὐ. ἐγώ, Rom.15:14; αὐ. Ἰησοῦς, Jhn.2:24; αὐ. καὶ οἱ μετ᾽ αὐτοῦ, Mrk.2:25; ὑμεῖς αὐ., Mrk.6:31; esp. (as freq in cl.) αὐ. ὁ, Mat.3:4 , Mrk.6:17 , Jhn.1', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0846') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12149, 'sense:G0878:primary', 3005, 13599, NULL, 'primary', 1, 'foolish', 'ἄφρων , -ον genitive -ονος (φρήν), [in LXX for כְּסִיל, נָבָל, etc. ;] without reason, senseless, foolish, expressing "want of mental sanity and sobriety, a reckless and inconsiderate habit of mind" (Hort; cf. MM, see word): Luk.11:40 12:20 , Rom.2:20 , 1Co.15:36 , 2Co.11:16 12:6 12:11 , 1Pe.2:15 ; opposite to φρόνιμος, 2Co.11:19; to συνιέντες, Eph.2:17. † (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0878') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12179, 'sense:G0906G:primary', 3035, 13627, NULL, 'primary', 1, 'to throw: throw', 'βάλλω , [in LXX for נפל, שׂום, ידד, etc. ;] prop., of a weapon or missile; then generally, of things and persons, lit. and metaphorically, to throw, cast, put, place : with accusative, before εἰς, Mat.4:18 , and frequently ἐπί, Mat.10:34; κάτω, Mat.4:6; ἔξω, Mat.5:13; ἀπό, Mat.5:29; ἐκ, Mrk.12:44; δρέπανον, Rev.14:19; μάχαιραν, Mat.10:34; κλῆρον, Mat.27:35; of fluids, to pour : Mat.9:17 , Jhn.13:5 ; pass., to be laid, to lie ill : Mat.9:2; ἐβλήθη (timeless aor., M, Pr. , 134), Jhn.15:6; intrans.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G0906G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12315, 'sense:G1027:primary', 3168, 13756, NULL, 'primary', 1, 'thunder', 'βροντή , -ῆς, ἡ, [in LXX for רַעַם ;] thunder : Mrk.3:17 , Jhn.12:29 , Rev.4:5 6:1 8:5 10:3, 4 11:19 14:2 16:18 19:6 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1027') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12357, 'sense:G1063:primary', 3210, 13796, NULL, 'primary', 1, 'for', 'γάρ , co-ordinating particle , contr. of γε ἄρα, verily then , hence, in truth, indeed, yea, then, why , and when giving a reason or explanation, for , the usage in NT being in general accord with that of cl.; __1. explicative and epexegetic : Mat.4:18 19:12 , Mrk.1:16 5:42 16:4 , Luk.11:3 o, Rom.7:1 , 1Co.16:5 , al. __2. Conclusive, in questions, answers and exclamations : Mat.9:5 27:23 , Luk.9:25 22:27 , Jhn.9:30 , Act.8:31 16:37 19:35 , Rom.15:26 , 1Co.9:10 , Php.1:18 (Ellic., in l.), 1Th.2:2', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1063') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12392, 'sense:G1093I:primary', 3243, 13831, NULL, 'primary', 1, 'earth: soil', 'γῆ , γῆς, ἡ, [in LXX for אֲדָמָה ,אֶרֶץ, etc. ;] __1. the earth, world : Luk.21:35 , Act.1:8 , Heb.11:13 , Rev.3:10 , al.; opposite to οὐρανός, Mat.5:18 11:25 , Mrk.13:27 , al. __2. land ; __(a) opposite to sea or water: Mrk.4:1 , Luk.5:3 , Jhn.6:21 , al.; __(b) as subject to cultivation : Mat.13:5 , Mrk.4:8 , Luk.13:7 , Heb.6:7 , al.; __(with) the ground : Mat.10:29 , Mrk.8:6 , Luk.24:5 , Jhn.8:6 , al.; __(d) a region, country : Luk.4:25 , Rom.9:28 , Jas.5:17 ; γῆ Ἰσραήλ, Mat.2:20, 21 ; Χαλδαίω', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1093I') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12397, 'sense:G1096:primary', 3248, 13834, NULL, 'primary', 1, 'to be', 'γίνομαι , Ion. and κοινή for Att. γίγν- (M. Pr. , 47; Bl., §6, 8 Mayser, 166 f.), [in LXX chiefly for היה ;] __1. of persons, things occurrences, to come into being, be born, arise, come on : Jhn.1:15 8:58 , 1Co.15:37 ; a first appearance in public, Mrk.1:4 , Jhn.1:6 , al.; before ἐκ (of birth), Rom.1:3 , Gal.4:4 ; διά, Jhn.1:3; βροντή, Jhn.12:29; σεισμός, Rev.6:12; γογγυσμός, Act.6:1; χαρά, Act.8:8 , many other similar exx.; ἡμέρα, Luk.22:66 , al.; ὀψέ, Mrk.11:19; πρωΐα, Mat.27:1; νύξ, Act.27:2', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1096') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12430, 'sense:G1125:primary', 3279, 13863, NULL, 'primary', 1, 'to write', 'γράφω , [in LXX chiefly for כּתב ]; __1. to scrape, graze (Hom.), and later (Hdt.) to sketch, draw . __2. to write ; __(a) of forming or tracing letters on writing material : Jhn.8:[6], Gal.6:11 , 2Th.3:17 ; __(b) to express in writing, commit to writing, record : Luk.1:63 , Jhn.19:21, 22 Rev.1:11, 19 al.; of scripture as a standing authority (Deiss., BS , 112ff.), γέγραπται, it stands written (Luther), Mat.4:4 , Mrk.7:6 , Luk.4:8 , Rom.1:17 , 1Co.1:31 , al.; id. before ἐν, Mrk.1:2 , Act.1:20 , ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1125') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12467, 'sense:G1161:primary', 3317, 13900, NULL, 'primary', 1, 'then', 'δέ (before vowels δ᾽; on the general neglect of the elision in NT, see WH, App. , 146; Tdf., Pr. , 96), post-positive conjunctive particle ; __1. copulative, but, in the next place, and, now (Abbott, JG , 104): Mat.1:2 ff., 2Co.6:15, 16 , 2Pe.1:5-7 ; in repetition for emphasis, Rom.3:21, 22, 9:30 , 1Co.2:6 , Gal.2:2 , Php.2:8 ; in transition to something new, Mat.1:18, 2:19 , Luk.13:1 , Jhn.7:14 , Act.6:1 , Rom.8:28 , 1Co.7:1 8:1 , al.; in explanatory parenthesis or addition, Jhn.3:19 , Rom.5:8 ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1161') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12469, 'sense:G1163:primary', 3319, 13902, NULL, 'primary', 1, 'be necessary', 'δεῖ impersonal (δέω), [in LXX chiefly for infin. with לְ ;] one must, it is necessary : with inf., Mat.26:54 , Mrk.13:7 , Act.5:29 , al.; with accusative and inf., Mat.16:21 , Mrk.8:31 , Jhn.3:7 , Act.25:10 , al.; with ellipse of accusative, Mat.23:23; of accusative, and inf., Mrk.13:14 , Rom.1:27 8:26 ; οὐ (μὴ) δεῖ (non licet), ought not, must not : Act.25:24 , 2Ti.2:24 ; impf., ἔδει, of necessity or obligation in past time regarding a past event (Bl., § 63, 4), Mat.18:33 , Luk.15:32 , Jhn.4:4 ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1163') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12493, 'sense:G1188:primary', 3344, 13927, NULL, 'primary', 1, 'right', 'δεξιός , -ά, -όν [in LXX chiefly for יָמִין ;] the right : Mat.5:29 , Jhn.18:10 , al.; ὅπλα δ., weapons carried in the right hand, i.e. for offence, 2Co.6:7 ; ἡ δ. χείρ, Mat.5:30 , Luk.6:6 , al.; ἡ δ. (sc. χείρ), Mat.6:3 , al.; ἐπὶ τὴν δ., in the right hand (R, txt., on R, mg.), Rev.5:1; διδόναι τὴν δ., in friend­ship (Deiss., BS , 251), Gal.2:9; metaphorically of power, τῇ δ. αὐτοῦ, Act.2:33 5:31 ; τὰ δ., the right side , Mrk.16:5; ἐκ δεξιῶν, on the right hand , with genitive, Mat.25:33, 34 , M', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1188') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12644, 'sense:G1325:primary', 3494, 14064, NULL, 'primary', 1, 'to give', 'δίδωμι , [in LXX chiefly for נָתַן (53 words in all) ;] to give —in various senses, accusative to context— bestow, grant, supply, deliver, commit, yield : absol., Act.20:35; with accusative of thing(s) and dative of person(s), Mat.4:9 5:31 , Jhn.1:12 , al. mult.; with dative of person(s), before ἐκ, Mat.25:8; id. with genitive part.. Rev.2:17; with accusative of person(s), Jhn.3:16 , Rev.20:13 , al.; δεξιάς, Gal.2:9; φίλημα, Luk.7:45; γνῶσιν, Luk.1:77; κρίσιν, Jhn.5:22; of seed yielding fruit, M', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1325') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12735, 'sense:G1417:primary', 3588, 14156, NULL, 'primary', 1, 'two', 'δύο , numeral , indecl. exc. in dative, δυσί, δυσίν (Attic δυοῖν), two : Mat.19:6 , Mrk.10:8 , Jhn.2:6 , al.; with pl. noun, Mat.9:27 10:10 , al.; οἱ, τῶν, τοὺς δ., Mat.19:5 20:24 , Mrk.10:8 , Eph.2:15 , al.; δ. ἐξ, Luk.24:13; distrib., ἀνὰ, κατὰ δ., two and two, two apiece : Luk.10:1 (WH, ἀνὰ δ. [δύο]), Jhn.2:6 , 1Co.14:27 ; δύο δύο (= ἀνὰ δ., as LXX, Gen.6:19 for שְׁנַיִם שְׁנַיִם, but not merely "Hebraism," cf. μυρία μυρία, Æsch., Pers. , 981, and for usage in π. and MGr., see M, Pr. , 21, 97', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1417') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12754, 'sense:G1437:primary', 3610, 14176, NULL, 'primary', 1, 'if', 'ἐάν , contr. fr. εἰ ἄν, conditional particle , representing something as "under certain circumstances actual or liable to happen," but not so definitely expected as in the case of εἰ with ind. (Bl., §65, 4; cf. Jhn.13:17 , 1Co.7:36 ), if haply, if ; __1. with subjc. (cl.); __(a) pres.: Mat.6:22 , Luk.10:6 , Jhn.7:17 , Rom.2:25, 26 al.; { __(b) aor. (= Lat. fut. pf.): Mat.4:9 16:26 (cf. ptcp. in Luk.9:25; M, Pr. , 230), Mrk.3:24 , Luk.14:34 , Jhn.5:43 , Rom.7:2 , al.; = cl. εἰ, with opt., Jhn.9:2', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1437') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12755, 'sense:G1438:primary', 3611, 14177, NULL, 'primary', 1, 'themself', 'ἑαυτοῦ , -ῆς, -οῦ, dative -ῷ, etc., accusative -όν, etc., pi. -ῶν, etc. (Att. contr. αὑτοῦ, etc); reflex pron. ; __1. prop, of 3rd person (Lat. sui, sibi, se), of himself, herself, itself , etc.: Mat.27:42 , Mrk.15:31 , Luk.23:35 , al.; added to a middle verb, διεμερίσαντο ἑαυτοῖς, Jhn.19:24; to an active verb, Act.14:14 (M, Pr. , 157); ἀφ᾽ ἑαυτοῦ, Luk.12:57 21:30 , Jhn.5:19 , al. (see: ἀπό); δι᾽ ἑαυτοῦ, Rom.14:14; ἐν ἑ., Mat.3:9 , Mrk.5:30 , al.; εἰς ἑ., Luk.15:17; καθ᾽ ἑαυτόν, Act.28:16 , Jas.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1438') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12806, 'sense:G1487G:primary', 3661, 14226, NULL, 'primary', 1, 'if', 'εἰ , conjunctive particle , used in conditions and in indirect questions. __I. Conditional, if ; __1. with indic, expressing a general assumption; __(a) pres.: before indic, pres., Mat.11:14 , Rom.8:25 , al.; before imperat., Mrk.4:23 9:22 , Jhn.15:18 , 1Co.7:9 , al.; before fut. indic., Luk.16:31 , Rom.8:11 , al.; before pf. or aor., with negation in apodosis, Mat.12:26 , Rom.4:14 , al.; similarly, before impf., Luk.17:6 , Jhn.8:39 ; before quæst., Mat.6:23 , Jhn.5:47 7:23 8:46 , 1Pe.2:20 ; __(', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1487G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12810, 'sense:G1492H:primary', 3666, 14238, NULL, 'primary', 1, 'to perceive: see', 'οἶδα , (from same root as εἶδον, which see), [in LXX chiefly for ידע ;] pf. with present meaning (plpf. as impf.; on irregular tense-forms, see App.), to have seen or perceived , hence, to know, have knowledge of : with accusative of thing(s), Mat.25:13 , Mrk.10:19 , Jhn.10:4 , Rom.7:7 , al.; with accusative of person(s), Mat.26:72 , Jhn.1:31 , Act.3:16 , al.; τ. θεόν, 1Th.4:5 , Tit.1:16 , al.; with accusative and inf., Luk.4:41 , al.; before ὅτι, Mat.9:6 , Luk.20:21 , Jhn.3:2 , Rom.2:2 11:2 , a', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1492H') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12829, 'sense:G1510:primary', 3685, 14257, NULL, 'primary', 1, 'to be', 'εἰμί , with various uses and significations, like the English verb to be . __I. As substantive verb. __1. Of persons and things, to be, exist : Act.17:28 , Jhn.1:1, 8:58, 17:5 , al; ὁ ὢν καὶ ὁ ἦν (for past ptcp.), Rev.1:4, 8, 4:8, 11:17, 16:5 (see Swete, Ap. , 5; M, Pr. , 228); τὰ (μὴ) ὄντα, Rom.4:17 , 1Co.1:28 . __2. Of times, events, etc., to be, happen, take place : Mat.24:3 , Mrk.14:2, 15:42 , Luk.21:23 , Jhn.4:6, 23, 5:10 , al. __3. to be present, be in a place, have come : Mat.2:13, 15 , M', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1510') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12834, 'sense:G1514:primary', 3689, 14261, NULL, 'primary', 1, 'be at peace', 'εἰρηνεύω (εἰρήνη), [in LXX chiefly for שׁלם, שׁקט ;] __1. to bring to peace, reconcile (so 1Ma.6:60 ). __2. to keep peace, be at peace : Mrk.9:50 , Rom.12:18 , 2Co.13:11 , 1Th.5:13 (cf. Sir.28:9; Cremer, 246). † (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1514') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12840, 'sense:G1519:primary', 3695, 14266, NULL, 'primary', 1, 'toward', 'εἰς , prep. with accusative, expressing entrance, direction, limit, into, unto, to, upon, towards, for, among (Lat. in, with accusative). __I. Of place. __1. After verbs of motion; __(a) of entrance into : Mat.8:23, 9:7 , Mrk.1:45 , Luk.2:15, 8:31 , al.; __(b) of approach, to or towards : Mrk.11:1 , Luk.6:8, 19:28 , Jhn.11:31, 21:6 , al.; __(with) before pl. and collective nouns, among : Mrk.4:7, 8:19, 20 , Luk.11:49 , Jhn.21:23 , al.; __(d) Of a limit reached, unto, on, upon : Mat.8:18, 21:1 , ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1519') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12841, 'sense:G1520:primary', 3696, 14267, NULL, 'primary', 1, 'one', 'εἷς ιά, ἕν, genitive ἑνός, μιᾶς, ἑνός, cardinal numeral, one ; __1. one , as opposite to many: Mat.25:15 , Rom.5:12 , 1Co.10:8 , al.; as subst., Rom.5:15 , Eph.2:14 ; id. with genitive partit., Mat.5:19 , al.; before ἐκ (ἐξ), Mrk.14:18 , Jhn.6:8 , al.; metaphorically, of union and concord, Jhn.10:30 17:11 , Rom.12:4-5 , Php.1:27 ; ἀπὸ μιᾶς (B1., § 44, 1), Luk.14:18; with neg., εἷς. . . οὐ (μή), more emphatic than οὐδείς, no one, none (cl.), Mat.5:18 10:29 , Luk.11:46 12:6 . __2. Emphatically, to', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1520') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12856, 'sense:G1537:primary', 3715, 14284, NULL, 'primary', 1, 'out from', 'ἐκ (ἐξ), prep. with genitive, from out of, from ( see Addendum, p. 492). This entry is included here, but in the print version the entry is found on p. 492. ἐκ , before a vowel ἐξ, prep. with genitive, of motion outwards, separation from (opposite to εἰς; = Lat. e, ex), from out of, from among, from . __I. Of Place, __1. of motion, out of, forth from, off from : Jhn.6:31 , Act.9:3 , Gal.1:8 , al.; esp. after verbs of motion, Mat.8:28 17:9 , Mrk.1:25 7:28 , Jhn.1:33 20:1 , Act.12:7, 17 27:30 , al', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1537') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12857, 'sense:G1538:primary', 3716, 14285, NULL, 'primary', 1, 'each', '1. every, every one, each, each one , Lat. quisque , (Homer), etc.; the singular is often joined with a pl. Verb, ἔβαν οἴκονδε ἕκαστος they went home every one of them , (Iliad by Homer); ἕκαστος ἐπίστασθε (Xenophon Historicus):—;the singular is also put in apposition with a pl. Noun, Τρῶας ἕκαστον ὑπήλυθε τρόμος (for Τρώων ἕκαστον)) fear seized them every one , (Iliad by Homer) 2. in plural all and each one , (Homer) 3. more definitely, εἷς ἕκαστος, Lat. unusquisque , every single one, (Herdotu', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1538') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12899, 'sense:G1577:primary', 3758, 14324, NULL, 'primary', 1, 'assembly', 'ἐκκλησία , -ας, ἡ (ἐκ-καλέω), [in LXX chiefly for קָהָל, otherwise for one of its cogn. forms ;] __1. prop., an assembly of citizens regularly convened (in Thuc., ii, 22, opposite to σύλλογος, a concourse ): Act.19:32, 39 41 . __2. In LXX of the assembly, congregation, community of Israel ( Deu.4:10 23:2 , al.): Act.7:38 , Heb.2:12 " (LXX) . __3. NT, esp. of an assembly or company of Christians, a (the) church ; __(a) of gatherings for worship : 1Co.11:18 14:19, 34 35 ; __(b) of local communitie', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1577') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12930, 'sense:G1607:primary', 3789, 14354, NULL, 'primary', 1, 'to depart', 'ἐκ-πορεύω [in LXX chiefly for יָצָא ;] to make to go out ; pass. and mid., to go forth : Luk.3:7 , Act.25:4 ; of demons leaving one possessed, Mat.17:21 (WH om.), Act.19:12; of excrement, Mk 719; before ἀπό, Mat.20:29 , Mrk.10:46 ; ἐκ, Mrk.13:1 (of the dead rising, Jhn.5:29 ); ἐκεῖθεν, Mrk.6:11; ἔξω, Mrk.11:19; είς, Mrk.10:17 , Jhn.5:29 ; ἐπί, with accusative of person(s), Rev.16:14; πρός, with accusative of person(s), Mat.3:5 , Mrk.1:5 ; εἰσπορ- (which see) καὶ ἐ., Act.9:28; metaphorically, to ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1607') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (12962, 'sense:G1636:primary', 3821, 14383, NULL, 'primary', 1, 'olive tree', 'ἐλαία (Attic, ἐλάα), -ας, ἡ [in LXX for זַיִת ;] __1. an olive tree : Rom.11:17, 24 , Rev.11:4 ; τ. ὄρος τῶν ἐ. (זַיִת הַר, Zec.14:4 ), the Mount of Olives: Mat.21:1 24:3 26:30 , Mrk.11:1 13:3 14:26 , Luk.19:37 22:39 ; τὸ καλούμενον ἐ. (T, ἐλαιών, which see), Luk.19:29 21:37 . __2. an olive (Aristoph.): Jas.3:12. † (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1636') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13032, 'sense:G2532:primary', 4819, 15320, NULL, 'primary', 1, 'and', 'καί , conj. , and __I. Copulative. __1. Connecting single words; __(a) in general : Mat.2:18, 16:1 , Mrk.2:15 , Luk.8:15 , Heb.1:1 , al. mult.; repeated before each of the terms in a series, Mat.23:23 , Luk.14:21 , Rom.7:12, 9:4 , al. __(b) connecting numerals (WM, §37, 4): Jhn.2:20 , Act.13:20 ; __(with) joining terms which are not mutually exclusive, as the part with the whole : Mat.8:33, 26:59 , Mrk.16:17 , Act.5:29 , al. __2. Connecting clauses and sentences : Mat.3:12 , Act.5:21 , al. mult.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2532') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13057, 'sense:G1722:primary', 3915, 14470, NULL, 'primary', 1, 'in/on/among', 'ἐν , prep , (the most frequently of all in NT), with dative (= Heb. בְּ, Lat. in, with abl.). __I. Of place, with dative of thing(s), of person(s), in, within, on, at, by, among : ἐν τ. πόλει, Luk.7:37; τ. οφθαλμῷ, Mat.7:3; τ. κοιλίᾳ, Mat.12:40; τ. ὄρει, 2Pe.1:18; τ. θρόνῳ, Rev.3:21; τ. δεξιᾷ τ. θεοῦ, Rom.8:34; ἐν ἡμῖν Abbott-Smith has ὑμῖν. , Luk.1:1; of books, ἐν τ. βιβλίῳ, Gal.3:10; τ. νόμῳ, Mat.12:5 , al.; ἐν τοῖς τ. Πατρός, in my Father''s house (RV; cf. M, Pr. , 103), Luk.2:49; trop., of th', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1722') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13087, 'sense:G3588:primary', 5861, 16309, NULL, 'primary', 1, 'the/this/who', 'ὁ , ἡ, τό, the prepositive article (ἄρθρον προτακτικόν), originally a demonstr. pron. (so usually in Hom.), in general corresponding to the Eng. definite article. __I. As demonstr. pron. __1. As frequently in Hom., absol., he (she, it), his (etc.): Act.17:28 (quoted from the poet Aratus). __2. Distributive, ὁ μὲν . . . ὁ δέ, the one . . . the other : 1Co.7:7 , Gal.4:22 ; pl., Act.14:4, 17:32 , Php.1:16 , al.; οἱ μὲν . . . ἄλλοι δέ, Mat.16:14 , Jhn.7:12 ; οἱ μεν̀ . . . ὁδέ, Heb.7:21, 23 . __3. In', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3588') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13141, 'sense:G1799:primary', 3997, 14547, NULL, 'primary', 1, 'before', 'ἐνώπιος , -ον (ὤψ), [in LXX for פָּנִים, etc. ;] face to face, in sight (Theocr.; ἄρτοι ἐ., Exo.25:29 ): neut., ἐνώπιον, in vernacular, with force of prep. with genitive [in LXX for פָּנִים, עַיִן, etc., cf. Dalman, Words , 31 f., 209 f., and Deiss., BS., 213], in NT, most frequently in Lk, Ac, Re, never in Mt, Mk, before, in the presence of : Luk.1:19 Luk.4:7 , Act.4:10 Act.6:5 , Rev.1:4 2:14 , al.; esp. ἐ. Κυρίου (θεοῦ), in the sight of God, or with God as witness or as judge, Rom.14:22 , 1Co.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1799') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13200, 'sense:G1854:primary', 4054, 14602, NULL, 'primary', 1, 'out/outside(r)', 'ἔξω adv. (ἐξ), [in LXX for חוּץ ;] __1. outside, without ; __(a) adverbially : Mat.12:46 , Mrk.3:31 11:4 , Luk.8:20 , Jhn.18:16 , al.; with art., ὁ ἔ., he who is without; metaphorically, in pl., οἱ ἔ., of those outside the Church, 1Co.5:12-13 , Col.4:5 (Lft., in l), 1Th.4:12; ὁ ἔ. ἄνθρωπος, 2Co.4:16; αἱ ἔ. πόλεις, Act.26:11; __(b) as prep. with genitive: Luk.13:33 , Act.21:5 , Heb.13:11-12 __2. After verbs of motion; __(a) adverbially, forth, out : Mat.5:13 Mrk.14:68 , Luk.22:62 , Jhn.19:4, 13 ,', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1854') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13256, 'sense:G1909:primary', 4112, 14657, NULL, 'primary', 1, 'upon/to/against', 'ἐπί (before a smooth breathing ἐπ᾽, before a rough breathing ἐφ᾽), prep. with genitive, dative, accusative (accusative most frequently in NT), with primary sense of superposition, on, upon . __I. C. genitive, __1. of place, answering the question, where? __(a) of the place on which, on, upon : ἐπὶ (τ.) γῆς, Mat.6:10, 19 , al.; τ. κεφαλῆς, 1Co.11:10; τ. νεφελῶν, Mat.24:3 o, al.; like ἐν, in constr. praegn. after verbs of motion: βάλλειν, Mrk.4:26; σπείρειν, ib. 31; ἔρχεσθαι, Heb.6:7 , al.; figura', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G1909') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13388, 'sense:G2033:primary', 4244, 14781, NULL, 'primary', 1, 'seven', 'ἐπτά , οἱ, αἱ, τά indecl., seven : Mat.12:45 18:22 (cf. ἑβδομηκοντάκις), Mrk.8:5 , al.; οἱ ἐ, Act.21:8 (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2033') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13427, 'sense:G2089:primary', 4282, 14838, NULL, 'primary', 1, 'still', 'ἔτι adv. , yet, as yet, still ; __1. of time ; __(a) of the present (adhuc): Mrk.5:35 , 1Co.3:3 15:17 , Gal.1:10 , al.; __(b) of the past, mostly with impf.: Mat.12:46 , Luk.8:49 15:20 , Jhn.20:1 , Act.9:1 , Rom.5:6 , 8, 2Th.2:5 , Heb.7:10 9:8 , al.; __(with) of the future : Luk.1:15 , 2Co.1:10 ; __(d) with a neg.: Mat.5:13 , Luk.16:2 20:36 , Heb.10:2 , Rev.3:12 20:3 , al. __2. Of degree, even, yet, still, further : with compar., Php.1:9 , Heb.7:15 ; of what remains, Mrk.12:6 , Jhn.4:35 7:33 , a', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2089') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13545, 'sense:G2181:primary', 4400, 14930, NULL, 'primary', 1, 'Ephesus', 'Ἔφεσος , -ου, ἡ Ephesus, a city in Asia Minor Act.18:19, 21 18:24, 27 19:1, 17 19:26 (on the genitive, see M, Pr. , 73) Act.20:16-17 , 1Co.15:32 16:8 , Eph.1:1 , 1Ti.1:3 , 2Ti.1:18 4:12 , Rev.1:11 2:1 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2181') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13557, 'sense:G2192:primary', 4412, 14941, NULL, 'primary', 1, 'to have/be', 'ἔχω , [in LXX for אָצֵל (ἐχόμενος), יֵשׁ,בַּעַל, etc., 59 words in all ;] (on the Aktionsart of the various tenses, see M, Pr. , 110, 145, 150, 183), to have , as in cl., in various senses and constructions. __I. Trans.; __1. 1. to have, hold, hold fast , etc.; __(a) to hold , as, in the hand : Rev.5:8 14:6 , al.; ἐν τ. χειρί, Rev.1:16 10:2 , al.; __(b) of arms and clothing, = φέρω, φορέω, to bear, wear : Mat.3:4 22:12 , al.; so frequently present ptcp. (LS, see word, A, I, 6; Bl., 74, 2), Mrk.1', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2192') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13594, 'sense:G2222:primary', 4448, 14974, NULL, 'primary', 1, 'life', 'ζωή , -ῆς, ἡ (ζάω), [in LXX chiefly for חַיִּים ;] life (in Hom., Hdt., = βίος, which see; later, existence, vita quâ vivimus , as distinct from βίος, vita quam vivimus ; opposite to θάνατος); __1. of natural life : Luk.16:25 , Act.8:33 , 1Co.15:19 , 1Ti.4:8 , Heb.7:3 , Jas.4:14 ; πνεῦμα ζωῆς, Rev.11:11; ψυχὴ ζωῆς ( Gen.1:30 ), Rev.16:3 ; of the life of one risen from the dead, Rom.5:10 , Heb.7:16 . __2. Of the life of the kingdom of God, the present life of grace and the life of glory which is ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2222') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13598, 'sense:G2226:primary', 4452, 14978, NULL, 'primary', 1, 'living thing', 'ζῷον (Rec. ζῶον, see LS, see word), -ου, τό (ζωός, alive), [in LXX for חַי (chiefly) and cognate forms; frequently in Wis ;] a living creature, an animal : Rev.4:6-9 5:6 ff. Rev.6:1 ff. Rev.7:11 14:3 15:7 19:4 ; ζῴων τ. αἷμα, Heb.13:11; ἄλογα ζ., 2Pe.2:12 , Ju 10 .† SYN. : θηρίον, in which the brutal, bestial element is emphasized, and which is never used of sacrificial animals. On the other hand, ζ. is the more comprehensive, as expressing the vital element common to the whole anima] creation (', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2226') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13599, 'sense:G2227:primary', 4453, 14979, NULL, 'primary', 1, 'to make alive', 'ζωο-ποιέω , ῶ [in LXX for חָיָה pi., hi., Jdg.21:14 , 4Ki.5:7 , Neh.9:6 , Job.36:6 , Psa.70:20 , Ecc.7:12 * ;] __1. in cl. (= ζωογονέω), to produce alive. __2. In LXX and NT, to make alive, cause to live, quicken ( DCG , ii, 606a; Cremer, 275): Jhn.5:21 6:53 , Rom.4:17 8:11 , 1Co.15:45 , 2Co.3:6 , Gal.3:21 . Pass., 1Co.15:22 15:36 , 1Pe.3:18 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2227') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13697, 'sense:G2316:primary', 4551, 15072, NULL, 'primary', 1, 'God', 'θεός , -οῦ, ὁ, ἡ ( Act.19:37 only; see M, Pr. , 60, 244), late voc., θεέ ( Mat.27:46; cf. Deu.3:24 , al.), [in LXX chiefly for אֱלֹהִים, also for אֵל and other cognate forms, יהוה, etc. ;] a god or deity, God . __1. In polytheistic sense, a god or deity : Act.28:6 , 1Co.8:4 , 2Th.2:4 , al.; pl., Ac. 14:11 19:26 , Gal.4:8 , al. __2. Of the one true God ; __(a) anarthrous : Mat.6:24 , Luk.20:38 , al.; esp. with prep. (Kühner 3, iii, 605), ἀπὸ θ., Jhn.3:2; ἐκ, Act.5:39 , 2Co.5:1 , Php.3:9 ; ὑπό, Ro', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2316') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13746, 'sense:G2362:primary', 4601, 15118, NULL, 'primary', 1, 'throne', 'θρόνος , -ου, ὁ [in LXX chiefly for כִּסֵּא, Exo.11:5 , al. ;] in Hom., a seat, chair. Later, a throne, chair of state, seat of authority; of kings: metaphorically, of God, Mat.5:34 , Act.7:49 " (LXX), Rev.1:4 , al.; by meton., for kingly power, sovereignty, Luk.1:32, 52 , Act.2:30 ; for an angelic hierarchy, Col.1:16; of Christ, Mat.19:28 , Rev.3:21 , al.; of Satan, Rev.2:13; τ. θηρίου, Rev.16:10; of the Apostles, Mat.19:28 , Luk.22:30 , cf. Rev.20:4; of πρεσβύτεροι, Rev.4:4 11:16 (on θ. τῆς χά', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2362') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13881, 'sense:G2476:primary', 4740, 15249, NULL, 'primary', 1, 'to stand', 'ἵστημι , and in late writers, also ἱστάνω (Veitch, see word; Bl., §23, 2; M, Pr. , 55), [in LXX chiefly for עמד, קוּם, also for נצב ni., hi., יצב hith., etc.]. __I. Trans, in pres., impf., fut. and 1 aor. act. and in the tenses of the pass. __1. to make to stand, to place, set, set up, establish, appoint : with accusative of person(s), Mrk.7:9 , Act.1:23 6:13 17:31 , Heb.10:9 ; id. before ἐπί, with accusative loc, Mat.4:5 , Luk.4:9 ; ἐν μέσῳ, Mat.18:2 , Mrk.9:36 , Jhn.8:[3]; ἐνώπιον, Act.6:6; πα', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2476') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13888, 'sense:G2480:primary', 4745, 15253, NULL, 'primary', 1, 'be strong', 'ἰσχύω (ἰσχύς), [in LXX for חָזַק, גִּבּוֹר, עָצַם, etc. ;] __1. to be strong in body : Mat.9:12 , Mrk.2:17 . __2. to be powerful, have power, prevail : Act.19:20 , Rev.12:8 ; before κατά, with genitive of person(s), Act.19:16; with inf., to be able (MM, Exp. , xv): Mat.8:28 26:40 , Mrk.5:4 9:18 (inf. understood) Mrk.14:37 , Luk.6:48 8:43 13:24 14:6, 29-30 16:3 20:26 , Jhn.21:6 , Act.6:10 15:10 25:7 27:16 ; with accusative, Php.4:13 , Jas.5:16 ; of things, to avail, be serviceable (MM, Exp. , l.w', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2480') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (13978, 'sense:G2545:primary', 4839, 15339, NULL, 'primary', 1, 'to kindle/burn', 'καίω [in LXX for בָּעַר, יָקַד, שָׂרַף, etc. ;] __1. to kindle, light : with accusative, λύχνον, Mat.5:15; pass., to be lighted, to burn : ptcp., Luk.12:35 , Rev.4:5 8:10 19:20 ; πυρί Heb.12:18 , Rev.8:8 21:8 ; metaphorically, Luk.24:32 , Jhn.5:35 . __2. to burn, destroy by fire : pass., Jhn.15:6 , 1Co.13:3 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2545') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14003, 'sense:G2570G:primary', 4864, 15366, NULL, 'primary', 1, 'good', 'καλός , -ή, -όν, [in LXX chiefly for טוֹבָה ,טוֹב, also for יָפֶה, etc. ;] __1. primarily, of outward form ("related to . . . ἀγαθός as the appearance to the essence," Cremer, 339), fair, beautiful : λίθοι (BV, goodly ), Luk.21:5. __2. In reference to use, of that which is well adapted to its ends, good, excellent : of fish, τ. καλά (opposite to σαπρά), Mat.13:48; σπέρμα, Mat.13:24, 27, 37, 38 ; καρπός, Mat.3:10 7:17-19 12:33 , Luk.3:9 [WH] 6:43; δένδρον (opposite to σαρπόν), Mat.12:33 , Luk.6:4', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2570G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14006, 'sense:G2570H:primary', 4867, 15367, NULL, 'primary', 1, 'Fair (Havens)', 'καλός , -ή, -όν, [in LXX chiefly for טוֹבָה ,טוֹב, also for יָפֶה, etc. ;] __1. primarily, of outward form ("related to . . . ἀγαθός as the appearance to the essence," Cremer, 339), fair, beautiful : λίθοι (BV, goodly ), Luk.21:5. __2. In reference to use, of that which is well adapted to its ends, good, excellent : of fish, τ. καλά (opposite to σαπρά), Mat.13:48; σπέρμα, Mat.13:24, 27, 37, 38 ; καρπός, Mat.3:10 7:17-19 12:33 , Luk.3:9 [WH] 6:43; δένδρον (opposite to σαρπόν), Mat.12:33 , Luk.6:4', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2570H') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14026, 'sense:G2590:primary', 4888, 15388, NULL, 'primary', 1, 'fruit', 'καρπός , -οῦ, ὁ [in LXX chiefly for פְּרִי ;] fruit : of trees, Mat.12:33 21:19 , Mrk.11:14 , Luk.6:44 13:6-7 ; of vines, Mat.21:34 , Mrk.12:2 , Luk.20:10 , 1Co.9:7 ; of fields, Mrk.4:29 , Luk.12:17 , 2Ti.2:6 , Jas.5:7 ; βλαστάνειν, Jas.5:18; ποιεῖν (cf. Heb. פְּרִי עָשָׂה), Mat.3:10 7:17-19 13:26 , Luk.3:9 6:43 8:8 13:9 , Rev.22:2 ; διδόναι, Mat.13:8 , Mrk.4:7-8 ; φέρειν, Mat.7:18 , Jhn.12:24 15:2, 4-5 15:8, 16 ; ἀποδιδόναι, Mat.21:41 , Rev.22:2 ; ὁ κ. τ. κοιλίας (בֶּטֶן פְּרִי, Deu.28:4 ), Luk', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2590') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14107, 'sense:G2662:primary', 4969, 15460, NULL, 'primary', 1, 'to trample', 'κατα-πατέω , -ῶ [in LXX for דָּרַךְ, רָמַס, שָׁאַף, etc. ;] to tread down, trample under foot : Mat.7:6 , Luk.12:1 ; pass., Mat.5:13 , Luk.8:5 . Metaphorical, τ. υἱὸν τ. θεοῦ, Heb.10:29. † (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2662') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14212, 'sense:G2768:primary', 5078, 15566, NULL, 'primary', 1, 'horn', 'κέρας , -ατος (pl. not irreg. as in Attic), τό, [in LXX chiefly for קָרַן ;] a horn : Rev.5:6 12:3 13:1, 11 17:3, 7 17:12, 16 ; of the projections at the corners of the altar ( Exo.29:12 , al.): Rev.9:13 . Metaphorical, as symbol of strength, κ. σωτηρίας (cf. Psa.18:3 , al.): Luk.1:69 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2768') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14297, 'sense:G2848:primary', 5166, 15649, NULL, 'primary', 1, 'seed', 'κόκκος , -ου, ὁ [in LXX: La 4:5 B א R (תּוֹלָע), Sir.45:11 * ;] a grain : Mat.13:31 17:20 , Mrk.4:31 , Luk.13:19 17:6 , Jhn.12:24 , 1Co.15:37 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2848') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14357, 'sense:G2902:primary', 5224, 15704, NULL, 'primary', 1, 'to grasp/seize', 'κρατέω , -ῶ (κράτος), [in LXX chiefly for חָזַק hi., also for אָחַז, etc. ;] __1. to be strong, mighty, hence, to rule, be master, prevail (so chiefly in cl.; in LXX: Est.1:1 , I Est.4:38 , Wis.14:19 , al.). __2. to get possession of, obtain, take hold of (Hdt., Thuc., al.): with genitive of thing(s) (M, Pr. , 65), Act.27:13; τ. χειρός, Mat.9:25 , Mrk.1:31 5:41 9:27 , Luk.8:54 ; with accusative of thing(s), Mat.12:11; with accusative of person(s), Mat.14:3 18:28 21:46 22:6 26:4, 48 ff., Mrk.3:21', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2902') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14416, 'sense:G2962G:primary', 5286, 15764, NULL, 'primary', 1, 'lord: God', 'κύριος , -α, -ον (also -ος, -ον), [in LXX (subst.) chiefly for יהוה, also for בַּעַל ,אָדוֹן, etc. ;] having power (κῦρος) or authority ; as subst., ὁ κ., lord, master ; __1. in general : with genitive of thing(s), Mat.9:38 20:8 , Mrk.12:9 13:35 , Luk.19:33 ; τ. σαββάτου, Mat.12:8 , Mrk.2:28 , Luk.6:5 ; with genitive of person(s), δούλου, etc., Mat.10:24 , Luk.14:21 , Act.16:16 , al.; absol, opposite to οἱ δοῦλοι, Eph.6:5 , 9 al.; of the Emperor (Deiss., LAE , 161), Act.25:26; θεοὶ πολλοὶ καὶ κ.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G2962G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14459, 'sense:G3004G:primary', 5329, 15809, NULL, 'primary', 1, 'to say', 'λέγω , [in LXX very freq., chiefly for אמר; λέγει for נְאֻם, Gen.22:16 , al. ;] __1. in Hom., to pick out, gather, reckon, recount . __2. In Hdt. and Att., to say, speak, affirm, declare : absol., Act.13:15, 24:10 ; before orat. dir., Mat.9:34 , Mrk.3:11 , Jhn.1:29 , al.; before ὅτι recit., Mrk.3:21 , Luk.1:24 , Jhn.6:14 , al.; accusative and inf., Luk.11:18 , Jhn.12:29 , al.; after another verb of speaking, προσφωνεῖν κ. λέγειν, Mat.11:17 , al.; ἀπεκρίθη (ἐλάλησεν) λέγων (καὶ λέγει; Dalman, Wor', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3004G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14521, 'sense:G3056:primary', 5390, 15865, NULL, 'primary', 1, 'word', 'λόγος , -ου, ὁ (λέγω) [in LXX chiefly for דָּבָר, also for מִלָּה ,אֵמֶר, etc. ;] __I. Of that by which the inward thought is expressed, Lat. oratio, sermo, vox, verbum. __1. a word , not in the grammatical sense of a mere name (ἔπος, ὄνομα, ῥῆμα), but a word as embodying a conception or idea: Mat.8:8 , Luk.7:7 , 1Co.14:9, 19 Heb.12:19 , al. __2. a saying, statement, declaration : Mat.19:22 (T om.), Mrk.5:36 7:29 , Luk.1:29 , Jhn.2:22 6:60 , Act.7:29 , al.; with genitive attrib., Act.13:15 , Rom', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3056') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14641, 'sense:G3165:primary', 5513, 15984, NULL, 'primary', 1, 'me', '1. apostrophe for με. 2. rarely for μοι, (Homer) (ML)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3165') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14688, 'sense:G3306:primary', 5560, 16026, NULL, 'primary', 1, 'to stay', 'μένω , [in LXX for קוּם ,עמד, etc. ;] to stay, abide, remain . __1. Intrans.; __(i) of place : before ἐν, Luk.8:27 , al.; παρά, with dative of person(s), Jhn.1:40 , al; σύν, Luk.1:56; καθ᾽ ἑαυτόν, Act.28:16; with adv., ἐκεῖ, Mat.10:11; ὧδε, Mat.26:38; metaphorically, 1Jn.2:18; of the Holy Spirit, Jhn.1:32, 33 14:17 ; of Christ, Jhn.6:56 15:4 , al.; ὁ θεός, 1Jn.4:15 , conversely, of Christians, Jhn.6:56 15:4 , 1Jn.4:15 , al.; ὁ λόγος τ. θεοῦ, 1Jn.2:14; ἡ ἀλήθεια, II Jo 2 , al. __(ii) Of time ; __', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3306') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14703, 'sense:G3319:primary', 5575, 16039, NULL, 'primary', 1, 'midst', 'μέσος , -η, -ον [in LXX chiefly for תָּוֶךְ ;] middle, in the middle or midst ; __1. prop., as an adj.: Luk.23:45 , Jhn.19:18 , Act.1:18 ; with genitive pl., Luk.22:55 , Jhn.1:26 ; genitive temp. (Bl., § 36, 13), μέσης νυκτός, Mat.25:6; μ. ἡμέρας, Act.26:13. __2. In adverbial phrases, neut., μέσον, τὸ μ., as subst.: ἀνὰ μέσον, with genitive, between (cl.; in LXX: Gen.1:4 , al.), elliptically (but see M, Pr. , 99), 1Co.6:5; = ἐν μ., among, in the midst of (El., § 39, 2; 40, 8; cf. in LXX: Jos.19:', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3319') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14746, 'sense:G3361:primary', 5619, 16081, NULL, 'primary', 1, 'not', 'μή , subjective negative particle , used where the negation depends on a condition or hypothesis, expressed or understood, as distinct from οὐ, which denies absolutely. μή is used where one thinks a thing is not, as distinct from an absolute negation. As a general rule, οὐ negatives the indic, μή the other moods, incl, ptcp. [In LXX for אֵין ,אַיִן ,אַל ] __I. As a neg. adv., not ; __1. with ref. to thought or opinion: Jhn.3:18 , Tit.1:11 , 2Pe.1:9 . __2. In delib. questions, with subjc. (M, Pr.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3361') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14826, 'sense:G3441:primary', 5705, 16161, NULL, 'primary', 1, 'alone', 'μόνος , -η, -ον, [in LXX chiefly for לְבַד ;] __1. adj. , alone, solitary, forsaken : with verb., Mat.14:23 , Mrk.6:47 , Luk.9:36 , al.; with pron., Mat.18:15 , Mrk.9:2 , al.; with subst., Mrk.9:8 , Luk.4:8 , al.; pleonast., οὐκ . . . εἰ μὴ μ., Mat.12:4 , Luk.6:4 , al.; attrib., only, (ὁ) μ. θεός, Jhn.5:44 17:3 , Rom.16:27 , 1Ti.1:17 , Ju 25 . __2. As adv ., __(a) neut., (μόνον, alone, only : referring to verb or predic., Mat.9:21 , Mrk.5:36 , Jas.1:22 , al. (see Bl., §44, 2); οὐ (μὴ) μ., Gal.4:', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3441') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14855, 'sense:G3466:primary', 5733, 16186, NULL, 'primary', 1, 'mystery', 'μυστήρισν , -ου, τό (μυέω), [in LXX: Dan LXX TH Dan.2:18 ff. (רָז), Tob.12:7, 11 , Jdth.2:2 , Wis.2:22 6:22 14:15, 23 , Sir.3:18 22:22 27:16-17, 21 , 2Ma.13:21 * ;] __1. that which is known to the μύστης (initiated), a mystery or secret doctrine, mostly in pl., τὰ μ. (Æsch., Hdt., al.). __2. In later writers (Menand., Incert., 168), that which may not be revealed (not, however, as in the modern sense, intrinsically difficult to understand), a secret or mystery of any kind (To, Jth, 2Mac, ll, wit', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3466') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14860, 'sense:G3471:primary', 5738, 16191, NULL, 'primary', 1, 'be foolish', 'μωραίνω (μωρός), [in LXX: Isa.19:11 , Jer.10:14 51:17 (בָּעַר ni.), 2Ki.24:10 , Isa.44:25 R (שָׂכַל ni., pi.)* ;] __1. cl., to be foolish, play the fool. __2. LXX and NT, causal, to make foolish : 1Co.1:20; pass., to become foolish : Rom.1:22; of salt that has lost its flavour, become tasteless : Mat.5:13 , Luk.14:34 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3471') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14915, 'sense:G3528:primary', 5793, 16248, NULL, 'primary', 1, 'to conquer', 'νικἀω , -ῶ (νίκη), [in LXX: Psa.51:4 (זָכָה), Pro.6:25 frequently (חָמַד); in 4Mac ;] to conquer, prevail : absol., of Christ, Rev.3:21 6:2 ; C. inf., Rev.5:5; of Christians, Rev.2:7, 11 2:17, 26 3:5, 12 3:21 21:7 ; before ἐκ (RV, come victorious from), Rev.15:2; as law-term (cl.), Rom.3:4 (LXX); with accusative of person(s), Luk.11:22 , Rev.11:7 13:7 ([WH], R, mg., om.); of Christ, Jhn.16:33 (τ. κόσμον), Rev.17:14; of Christians, 1Jn.4:4; τ. πονηρόν, 1Jn.2:13-14; αὐτόν (ref. to ὁ κατήγωρ, 1Jn.2', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3528') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14977, 'sense:G3586:primary', 5859, 16307, NULL, 'primary', 1, 'wood', 'ξύλον , -ου, τό [in LXX chiefly for עֵץ ;] __1. wood : 1Co.3:12 , Rev.18:12 . __2. a piece of wood, hence, anything made of wood, as, __(a) a cudgel, staff : pl., Mat.26:47, 55 , Mrk.14:43, 48 , Luk.22:52 ; __(b) stocks, for confining the feet ( Job.33:11 , סַד) : Act.16:24; __(with) a beam to which malefactors were bound (late Gk.), in LXX, of a gibbet ( Deu.21:22-23 ), in NT, of the Cross: Act.5:30 10:39 13:29 , Gal.3:13 , 1Pe.2:24 . __3. In late writers (see MM, xvii), a tree ( Gen.1:29 , Isa', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3586') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (14982, 'sense:G3592:primary', 5865, 16313, NULL, 'primary', 1, 'this', 'ὅδε , ἥδε, τόδε (the old demonstr. pron., ὁ + the enclitic δε), = Lat. hicce, this (here), referring prop, to what is present, can be seen or pointed out : of a person just named, τῇδε (= ταύτῃ), Luk.10:39; neut. pl., τάδε (λέγει), referring to words which follow (so in Att.., and see MM, xvii) : Act.21:11 , Rev.2:1, 8 2:12, 18 3:1, 7 3:14 ; εἰς τήνδε τ. πόλιν (= Att.. τῇ καὶ τῇ, Plat., Legg., iv, 721 B), such and such a city, Jas.4:13. † (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3592') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15135, 'sense:G3739:primary', 6015, 16463, NULL, 'primary', 1, 'which', 'ὅς , ἥ, ὅ, the postpositive article (ἄρθρον ὑποτακτικόν). __I. As demonstr. pron. = οὗτος, ὅδε, this, that , also for αὐτός, chiefly in nom.: ὅς δέ, but he (cf. ἦ δὲ ὅς, frequently in Plat.), Mrk.15:23 , Jhn.5:11 ; ὃς μὲν . . . ὃς δέ, the one . . . the other , Mat.21:35, 22:5, 25:15 , Luk.23:33 , Act.27:14 , Rom.14:5 , 1Co.11:21 , 2Co.2:18 , Ju 22 ; neut., ὃ μὲν . . . ὃ δέ, the one . . . the other, some . . . some , Mat.13:8, 23 , Rom.9:21 ; ὃς (ὃ) μὲν . . . (ἄλλος (ἄλλο)) . . . ἕτερος, Mrk.4:4 ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3739') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15153, 'sense:G3756:primary', 6033, 16481, NULL, 'primary', 1, 'no', 'οὐ , before a vowel with smooth breathing οὐκ, before one with rough breathing οὐχ (but improperly οὐχ ἰδού, Act.2:7 , WH, mg.; cf. WH, Intr. , §409; M, Pr. , 44, 244), [in LXX for אֵין ,אַיִן ,לֹא ;] neg. particle , not, no , used generally with indic, and for a denial of fact (cf . μή); __1. absol. (accented), οὔ, no : Mat.13:29 Jhn.1:21 21:5 ; οὒ οὕ, Mat.5:37 Jas.5:12 . __2. Most frequently negativing a verb or other word, Mat.1:25 10:26, 38 , Mrk.3:25 9:37 , Jhn.8:29 , Act.7:5 , Rom.1:16 , P', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3756') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15158, 'sense:G3762:primary', 6039, 16487, NULL, 'primary', 1, 'none', 'οὐδείς , -δεμία, -δέν (also in WH, txt., the Hellenistic forms -θείς, -θέν, Luk.22:35 23:14 , Act.15:9 19:27 26:26 , 1Co.13:2 , 2Co.11:8 ; cf. BL, §6, 7; M, Pr. , 56n, Thackeray, Gr. , 58), related to μηδείς as οὐ to μή, no, no one, none : with nouns, Luk.4:24 , Jhn.10:41 , Rom.8:1 , al.; absol., Mat.6:24 , Mrk.3:27 , Luk.1:61 , Jhn.1:18 , Act.18:10 , Rom.14:7 , al. mult.; with genitive partit., Luk.4:26 , Jhn.13:28 , al.; neut., οὐδέν, Mat.10:26 , al.; id. with genitive partit., Luk.9:36 , Act.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3762') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15171, 'sense:G3775:primary', 6052, 16500, NULL, 'primary', 1, 'ear', 'οὖς genitive, ὠτός, τό, [in LXX chiefly for אֹזֶן ;] the ear : Mat.13:16 , Mrk.7:33 , Luk.22:50 , 1Co.2:9 12:16 , 1Pe.3:12 ; ἐν τ. ὠσί, Luk.4:21; εἰς τ. ὦτα ἀκούεσθαι, Act.7:57; γίνεσθαι, Luk.1:44; εἰσέρχεσθαι, Jas.5:4; εἰς τ. οὖς ἀκούειν, Mat.10:27; πρὸς τ. οὖς λαλεῖν, Luk.12:3; τὰ ὦ. συνέχειν (MM, xviii), Act.7:57. Metaphorical, of understanding, perceiving, knowing : Mat.13:16; ὁ ἔχων (εἴ τις ἔχει) οὖς ἀκουσάτω, Rev.2:7, 11 2:17, 29 3:6, 13 13:9 ; ὁ ἔχων (ὃς ἔχει, εἴ τις ἔχει) ὦτα (ἀκούειν) ἀ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3775') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15174, 'sense:G3778:primary', 6055, 16503, NULL, 'primary', 1, 'this/he/she/it', 'οὗτος , αὕτη, τοῦτο, genitive, τούτου, ταύτης, τούτου, [in LXX chiefly for זֹאת ,זֶה ;] demonstr. pron. (related to ἐκεῖνος as hic to ille), this ; __1. as subst., this one, he ; __(a) absol.: Mat.3:17 , Mrk.9:7 , Luk.7:44, 45 , Jhn.1:15 , Act.2:15 , al.; expressing contempt (cl.), Mat.13:55, 56 , Mrk.6:2 , 3, Jhn.6:42 , al.; εἰς τοῦτο, Mrk.1:38 , Rom.14:9 ; μετὰ τοῦτο (ταῦτα; V. Westc. on Jhn.5:1 ), Jhn.2:12 11:7 , al.; __(b) epanaleptic (referring to what precedes): Mat.5:19 , Mrk.3:35 , Luk.9', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3778') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15185, 'sense:G3788:primary', 6066, 16513, NULL, 'primary', 1, 'eye', 'ὀφθαλμός , -οῦ, ὁ, [in LXX chiefly for עַיִן ;] the eye (as in cl., chiefly pl.): Mat.5:38 , Mrk.9:47 , Luk.6:41 , Jhn.9:6 , al.; τοὺς ὀ. ἐξορύθσσειν (figuratively), Gal.4:15; ἐπᾶραι, Luk.6:20 , Jhn.6:5 ; ἀνοῖξα, Act.9:40; id., of restoring sight, Mat.20:33 , Jhn.9:10 , al.; ἐν ῥιπῇ ὀφθαλμοῦ, 1Co.15:52; by anthropom., of God, Heb.4:13 , 1Pe.3:12 ; pleonastically (cf. Thackeray, Gr. , 42f.), εἶδον οἱ ὀ. μοθ, Luk.2:30 (similarly, ib. 4:20 10:23 , Jhn.12:40 , 1Co.2:9 , 1Jn.1:1 , Rev.1:7 ). Metaphor', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3788') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15244, 'sense:G3842:primary', 6125, 16567, NULL, 'primary', 1, 'always', 'πάντοτε adv. of time (πᾶς), [in LXX: Wis.11:21 19:18 * ;] in late writers (once in Arist.) for διαπαντός, ἑκάστοτε, at all times, always : Mat.26:11 , Mrk.14:7 , Luk.15:31 , Jhn.6:34 , Rom.1:10 , and frequently in Paul. Epp (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3842') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15254, 'sense:G3850:primary', 6134, 16575, NULL, 'primary', 1, 'parable', 'παραβολή , -ῆς, ἡ (παραβάλλω), [in LXX (cf. McNeile, Mt., 185): Num.23:7 , Deu.28:37 , Psa.44:14 , Pro.1:6 , Eze.12:22 , al. (מָשַׁל), Sir.47:17 (חִידָה), al. mutt. in Sir, Wis.5:3 ;] __1. a placing beside, juxtaposition (Polyb., al.). __2. a comparing, comparison (Plat., Arist., al.). __3. a comparison, illustration, analogy, figure (Arist., al.) : Mat.24:32 , Mrk.3:23 , Heb.9:9 11:19 ; specif. of the pictures and narratives drawn from nature and human life which are characteristic of the synop', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3850') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15262, 'sense:G3857:primary', 6143, 16582, NULL, 'primary', 1, 'paradise', 'παράδεισος , -ου, ὁ (an Oriental word, first used by Xen. of the parks of Persian kings and nobles) [in LXX chiefly for גַּן, Gen.1:8 ff., al.; also for עֵדֶן, Isa.51:3; פַּרְדֵּס, Neh.2:8 , Ecc.2:5 ;] __1. a park, pleasure-ground, garden (LXX), an orchard (in π., see MM, ii, xviii; Deiss., BS, 148). __2. Paradise, the abode of the blessed dead : Luk.23:43 , 2Co.12:4 , Rev.2:7 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3857') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15364, 'sense:G3956:primary', 6247, 16681, NULL, 'primary', 1, 'all', 'πᾶς , πᾶσα, πᾶν, genitive, παντός, πάσης, παντός, [in LXX chiefly for כֹּל ;] all, every . __I. As adj., __1. with subst. anarth., all, every, of every kind : Mat.3:10 4:23 , Mrk.9:49 , Luk.4:37 , Jhn.2:1 o, Act.27:20 , Rom.7:8 , Rev.18:17 , al. mult.; pl., all , Act.22:15 , Rom.5:12 , Heb.1:6 , al.; of the highest degree, π. ἐξουσία (προθυμία, χαρά), Mat.28:18 , Act.17:11 , Phi 2:29 , al.; also the whole (though in this sense more frequently with art.), Mat.2:3 , Act.2:36 , Rom.11:26 . __2. C. ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G3956') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15450, 'sense:G4043:primary', 6338, 16772, NULL, 'primary', 1, 'to walk', 'περι-πατέω , -ῶ [in LXX chiefly for הָלַךְ pi., hith. ;] to walk : absol., Mat.9:5 , Mrk.5:42 , Luk.5:23 , Jhn.1:36 ; with pred., γυμνός, Rev.16:15; ἐπάνω Luk.11:44; διά, with genitive, Rev.21:24; ἐν, Mrk.11:27 12:38 , Jhn.7:1 11:54 , Rev.2:1 , al.; ἐν τ. σκοτίᾳ, figuratively, Jhn.8:12 12:35 , 1Jn.1:6-7 Jn 2:11 ; ἐπί, with genitive, Mat.14:26; id. with dative, Mat.14:25, 29 ; μετά, Jhn.6:66 , Rev.3:4 ; παρά, with accusative, Mat.4:18. Metaphorical, of living, passing one''s life, conducting onese', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4043') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15507, 'sense:G4098:primary', 6395, 16829, NULL, 'primary', 1, 'to collapse', 'πίπτω [in LXX chiefly for נָפַל ;] to fall ; __1. of descent, to fall, fall down or from : before ἐπί, with accusative loc., Mat.10:29 , al.; εἰς, Mat.15:14 , al.; ἐς μέσῳ, with genitive, Luk.8:7; παρὰ τ. ὁδόν, Mat.13:4 , Mrk.4:4 , Luk.8:5 ; before ἀπό, Mat.15:27 , al.; ἐκ, Mrk.13:25 , Luk.10:18 , Rev.8:10 9:1 . Metaphorical: ὁ ἥλιος, before ἐπί, Rev.7:16; ἀχλὺς κ. σκότος, Act.13:11; ὁ κλῆρος, Act.1:26; ὑπὸ κρίσιν, Jas.5:12. __2. Of prostration, __(a) of persons, to fall prostrate, prostrate one', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4098') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15600, 'sense:G4183:primary', 6488, 16919, NULL, 'primary', 1, 'much', 'πολύς , πολλή, πολύ, [in LXX chiefly for רַב and cognate forms ;] __1. as adj. , much, many, great , of number, space, degree, value, time, etc.: ἀριθμός, Act.11:21; ὄχλος, Mrk.5:24; θερισμός, Mat.9:37; χόρτος, Jhn.6:10; χρόνος, Mat.25:19; γογγυσμός, Jhn.7:12; πόνος, Col.4:13; δόξα, Mat.24:30; σιγή, Act.21:40; pl., προφῆται, Mat.13:17; ὄχλοι, Mat.4:25; δαιμόνια, Mrk.1:34; δυνάμεις, Mat.7:22 , __2. As subst., pl. masc, πολλοί, many (persons): Mat.7:22 , Mrk.2:2 , al.; with genitive partit., Mat.3', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4183') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15666, 'sense:G4245G:primary', 6556, 16981, NULL, 'primary', 1, 'elder: Elder', 'πρέσβυς , -εως, ὁ poët. form of πρεσβύτης (which see), [in LXX (= πρεσβευτής, an ambassador): Num.21:20 (21), al. (מֲלְאָךְ), Isa.13:8 57:9 (צִיר), 1Ma.9:70 , al. ;] an old man. Compar., πρεσβύτερος, -α, -ον, [in LXX chiefly for זָקֵן ;] __1. of age, elder : ὁ νἱὸς ὁ π., Luk.15:25; as subst., opposite to νεανίσκοι, Act.2:17; to νεώτερος, 1Ti.5:1-2; of the religious leaders of the past, Mat.15:2 , Mrk.7:3 , 5, Heb.11:2 (= οἱ πατέρες, Heb.1:1 ). __2. Of dignity, rank or office (as found in π. and ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4245G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15874, 'sense:G4442:primary', 6764, 17182, NULL, 'primary', 1, 'fire', 'πῦρ genitive, πυρός, τό, [in LXX chiefly and very frequently for אֵשׁ ;] fire : Mrk.9:22 , Luk.3:9 , Jhn.15:6 , Act.2:10 , 1Co.3:13 , Jas.3:5 , Rev.8:5 , al; π. καὶ θεῖον, Luk.17:29; κατακαίειν (ἐν) π., Mat.13:40 , Rev.17:16 18:8 ; καίεσθαι πυρί, Heb.12:18 , Rev.8:8 21:8 ; φλὸξ πυρός, Act.7:30 , 2Th.1:8 , Heb.1:7 , Rev.1:14 2:18 19:12 ; λαμπάδες πυρός, Rev.4:5; στῦλοι πυρός, Rev.10:1; ἄνθρακες πυρός, Rom.12:20 (LXX); γλῶσσαι ὡσεὶ πυρός, Act.2:3; δοκιμάζειν (πυροῦσθαι) διὰ πυρός, 1Pe.1:7 , Rev.3:', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4442') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (15891, 'sense:G4459:primary', 6781, 17199, NULL, 'primary', 1, 'how?!', 'πῶς , interrog. adv. , correl. of ὅπως, __1. prop., in direct questions, how? : with indic., Mat.12:29 , Mrk.3:23 , Luk.11:18 , Jhn.3:4 , al.; καὶ π., Mrk.4:13 , Luk.20:44 ; π. οὖν, Mat.12:26; π. οὐ, Mat.16:11 , Luk.12:56 ; in deliberative questions (cf. Bl., §64, 6), with subjc., Mat.23:33 26:54 ; π. οὖν, Rom.10:14; π. δέ, Rom.10:14, 15 ; before ἄν, with optative, Act.8:31. __2. As sometimes in cl. but more frequently and increasingly so in late writers (see WM, §57, 2; Bl., §70, 2; Thumb, MGr.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4459') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16079, 'sense:G4621:primary', 6970, 17374, NULL, 'primary', 1, 'grain', 'σῖτος , -ου, ὁ [in LXX chiefly for דָּגָן ;] wheat, corn : Mat.3:12 13:25, 29-30 Mrk.4:28 , Luk.3:17 12:18 16:7 22:32 , Jhn.12:24 , Act.27:38 , 1Co.15:37 , Rev.6:6 18:13 .† σιτίοι, -ου, τό (dimin. of σῖτος), [in LXX: Pro.30:22 (לֶחֶם)* ;] __1. corn, grain : Act.7:12 (but see 131., § 9, 1). __2. Mostly in pl., σιτία, bread, food, provisions (LXX, l.with, Hdt., al.).† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4621') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16097, 'sense:G4687:primary', 7045, 17441, NULL, 'primary', 1, 'to sow', 'σπείρω [in LXX chiefly for זָרַע ;] to sow (seed): absol., Mat.6:26 13:3-4, 18 25:24, 26 , Mrk.4:3-4 , Luk.8:5 12:24 , Jhn.4:36 , 2Co.9:10 ; with accusative of thing(s), Mat.13:24, 27 13:37, 39 , Mrk.4:32 , Luk.8:5 , 1Co.15:36-37 ; before εἰς, Mat.13:22 , Mrk.4:18 ; ἐν, Mat.13:24, 31 ; ἐπί, with genitive, Mrk.4:31; ἐπί, with accusative, Mat.13:20, 23 , Mrk.4:16, 20 ; παρά, with accusative, Mat.13:19. Metaphorical: 1Co.9:11 15:42-44 , Gal.6:7-8 , Jas.3:18 ; in proverbial sayings, Mat.25:24, 26 , ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4687') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16150, 'sense:G4690G:primary', 7048, 17444, NULL, 'primary', 1, 'seed: offspring', 'σπέρμα , -τος, τό (σπείρω) [in LXX chiefly for זֶרַע ;] seed ; __(a) of plants : Mat.13:24, 27 13:37-38 , 2Co.9:10 ; pl., Mat.13:32 , Mrk.4:31 , 1Co.15:33 ; metaphorically, of an escaping remnant (שָׂרִיד, Isa.1:9; cf. Wis.14:6; Plat., Tim., 23c; FlJ, Ant. , xi, 5, 3), Rom.9:29; __(b) of men (as γονή; Lat. semen genitale; so in cl.; cf. in LXX, Lev.15:16 , al.): Heb.11:11 ; metaphorically, of the divine influence, 1Jn.3:9; by meton. (as frequently in poets), seed, offspring, posterity : Mat.22:2', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4690G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16164, 'sense:G4703:primary', 7061, 17458, NULL, 'primary', 1, 'seed', 'σπόρος , -ου, ὁ (σπείρω), [in LXX chiefly for זֶרַע ;] = σπορά, __1. sowing or seedtime. __2. seed sown (so usually in late Gk.): Mrk.4:26-27 , Luk.8:5, 11 , 2Co.9:10 a (LTr.); metaphorically, of almsgiving, 2Co.9:10 b.† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4703') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16239, 'sense:G4771:primary', 7134, 17526, NULL, 'primary', 1, 'you', 'σύ , pron. of 2nd of person(s), thou, you , genitive, σοῦ, dative, σοί, accusative, σέ, pl., ὑμεῖς, -ῶν, -ῖν, -ᾶς (enclitic in oblique cases sing., except after prep. (BL, §48, 3), though πρὸς σέ occurs in Mat.25:39 ). Nom. for emphasis or contrast: Jhn.1:30, 4:10, 5:33, 39, 44 , Act.4:7 , Eph.5:32 ; so also perhaps σὺ εἶπας, Mat.26:64 , al. (M, Pr. , 86); before voc., Mat.2:6 , Luk.1:76 , Jhn.17:5 , al.; sometimes without emphasis (M, Pr. , 85f.), as also in cl., but esp. as rendering of Heb. p', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4771') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16448, 'sense:G4969:primary', 7349, 17728, NULL, 'primary', 1, 'to slaughter', 'σφάζω [in LXX chiefly for שָׁחַט ;] to slay, slaughter (esp. of victims for sacrifice): ἀρνίον, Rev.5:6, 12 13:8 ; of persons, 1Jn.3:12 , Rev.5:9 6:4, 9 18:24 ; ἐσφαγμένη εἰς θάνατον (RV, smitten unto death), Rev.13:3 (cf. κατα-σφάζω).† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G4969') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16548, 'sense:G5064:primary', 7452, 17823, NULL, 'primary', 1, 'four', 'τέσσαρες (and Ion. and late -ερεν, and late accusative -εν; see WH, App. , 150; M, Pr. , 36, 45 f.), οἱ, αἱ, -αρα, τά, genitive, -ων, four : Mat.24:31 , Mrk.2:3 , Luk.2:37 , Jhn.11:17 19:23 , Act.10:11 , Rev.4:4 , 6, al (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5064') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16590, 'sense:G5101:primary', 7494, 17863, NULL, 'primary', 1, 'which?', 'τίς , neut., τί, genitive, τίνος, interrog. pron. , [in LXX for מָה ,מִי ;] in masc. and fem., who, which, what? ; in neut., which, what? , used both in direct and in indirect questions. __I. I. As subst., __1. 1. masc., fem.: τίς; who, what? , Mat.3:7 26:68 ; Mrk.11:28 , Luk.9:9 , al. mult.; with genitive partit., Act.7:52 , Heb.1:5 , al; before ἐκ (= genitive partit.), Mat.6:27 , Luk.14:28 , Jhn.8:46 ; = ποῖος, Mrk.4:41 6:2 , Luk.19:3 , Act.17:19 , al.; = πότερος (M, Pr. , 77), Mat.21:31 27:17', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5101') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16696, 'sense:G5204:primary', 7602, 17966, NULL, 'primary', 1, 'water', 'ὕδωρ genitive, ὕδατος, τό, [in LXX chiefly for מַיִם ;] water : Mat.3:16 , Mrk.1:10 , Luk.7:44 , Jhn.4:7 , Jas.3:12 , Rev.8:10 , al.; pl., Mat.14:28-29 , Jhn.3:23 , Rev.1:15 , al.; βαπτίζειν (ἐν) ὕδατι, Mat.3:11 , Mrk.1:8 , Jhn.1:26 , al.; τ. λυυτρὸν τοῦ ὕ., Eph.5:26; opposite to οἴνος, Jhn.2:9 4:46 ; αἷμα, Jhn.19:34 , Heb.9:19 , 1Jn.5:6 Jn 5:8 Mat.17:15 Mrk.9:22 ; πνεῦμα, Jhn.1:26, 31 1:33 ; πνεῦμα καὶ πῦρ, Mat.3:11 , Luk.3:16 ;ἐξ ὕ. κ. πνεύματος γεννηθῆναι, Jhn.3:5; metaphorically, of divine t', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5204') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16756, 'sense:G5259G:primary', 7663, 18021, NULL, 'primary', 1, 'by/under: by', 'ὑπό (before smooth breathing ὑπ᾽, Mat.8:9 b, Luk.7:8 b; before rough breathing ὑφ᾽, Rom.3:9; on the neglect of elision in Mt, Lk, ll. witha, Gal.3:22 , see WH, App. , 146; Tdf., Pr. , iv), prep. with genitive, dative (not in NT), accusative __I. C. genitive, primarily of place, under , hence, metaphorically, of the efficient cause, by : after passive verbs, with genitive of person(s), Mat.1:22 , Mrk.1:5 , Luk.2:18 , Jhn.14:21 , Act.4:11 , 1Co.1:11 , Heb.3:4 , al.; with genitive of thing(s), Mat.', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5259G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16810, 'sense:G5315:primary', 7717, 18078, NULL, 'primary', 1, 'to eat', 'φάγομαι Hellenistic for cl. ἔδομαι, see: ἐσθίω. ἐσθίω , and (poet, and late prose) ἔσθω, [in LXX chiefly for אכל ;] to eat ; __(a) absol.: Mat.14:20, 21 Mrk.6:31 , Jhn.4:31 , al.; ἐν τ. φαγεῖν (on this aor. form, see M, Pr. , 111), 1Co.11:21; διδόναι φαγεῖν, with dative of person(s), Mrk.5:43 , al.; ἐ. καὶ πίνειν, Mat.6:25, 31 Luk.10:7 , al.; of ordinary use of food and drink, 1Co.9:4 11:22 ; of partaking of food at table, Mrk.2:16 , Luk.5:30 , al.; opposite to fasting, Mat.11:18 , Luk.5:33 , al', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5315') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16842, 'sense:G5342:primary', 7748, 18107, NULL, 'primary', 1, 'to bear/lead', 'φέρω [in LXX chiefly for בּוֹא. hi., also for נָשָׂא, etc. ;] to bear ; __1. to bear, carry : with accusative, Luk.23:26 24:1 , Jhn.19:39 , Heb.1:3 (see Westc., in l); pass., Act.2:2 27:15, 17 Heb.6:1 , 2Pe.1:17-18 ; of the mind, 2Pe.1:21. __2. to bear, endure : with accusative of thing(s), Heb.12:20 13:13 ; with accusative of person(s), Rom.9:22. __3. to bring, bring forward : with accusative of person(s), Act.5:16; id. before πρός, Mrk.1:32 2:3 9:17, 19-20 ; ἐπί, Luk.5:18; with dative, Mrk.7:3', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5342') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16963, 'sense:G5456H:primary', 7874, 18229, NULL, 'primary', 1, 'voice/sound: noise', 'φωνή , -ῆς, ἡ, [in LXX chiefly and very frequently for קוֹל ;] a voice ; __(a) prop., of persons, Mat.2:18 (LXX), al.; φ. αἴρειν (ἐπαίρειν), Luk.17:13 , Act.2:14 , al.; φ. μεγάλῃ εἰπεῖν (λέγειν, φωνεῖν, etc.), Luk.8:28 , Act.7:57 , Rev.5:12 , al.; γίνεται (ἔρχεται) φ. ἐκ τ. οὐρανῶν (ἐξ οὐρανοῦ), Mrk.1:11 , Luk.3:22 , Jhn.12:28 , al. (cf. DCG , ii, 810a; Dalman, Words , 204f.); ἀκούειν φωνήν (-ῆς; see: ἀκούω), Act.9:4 , 7 al.; φ. βοῶντος, Mat.3:3 , Mrk.1:3 , Luk.3:4 , Jhn.1:23 " (LXX) ; τ. θεοῦ, ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5456H') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (16995, 'sense:G5485:primary', 7904, 18258, NULL, 'primary', 1, 'grace', 'χάρις, -ιτος, ἡ Abbott-Smith does not include the article here. , accusative, χάριν (χάριτα in Act.24:27 , Ju 4 ; see WH, App. , 157), [in LXX chiefly for חֵן ;] __1. objectively, that which causes favourable regard, gracefulness, grace, loveliness of form, graciousness of speech (cl.; Ecc.10:12 , Sir.21:16 , al.): Col.4:6 ; λόγοι τ. χάριτος (genitive qual.), Luk.4:22. __2. Subjectively, __(a) on the part of the giver, grace, graciousness, kindness, goodwill, favour : Luk.2:52 , Act.7:10 , al.; ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5485') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (17065, 'sense:G5552:primary', 7977, 18327, NULL, 'primary', 1, 'golden', 'Χρύσεος , -εα, -εον (-οῦς, -ῆ, -οῦν; on accusative sing. fem., -ᾶν, Rev.1:13 and genitive pl. uncontr., -εων, Rev.2:1 , LTr., see M, Pr. , 48 and cf. Thackeray, Gr. , x, 172 f.) (χρυσός), [in LXX chiefly for זָהָב ;] golden, i.e. made or overlaid with gold: 2Ti.2:20 , Heb.9:4 , Rev.1:12-13, 20 2:1 4:4 5:8 8:3 9:13, 20 14:14 15:6-7 17:4 21:15 .† (AS)', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5552') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (17130, 'sense:G5613:primary', 8045, 18395, NULL, 'primary', 1, 'as/when', 'ὡς , adverbial form of the relative pron. ὅς, ἥ, ὅ. __I. As relat. adv. of manner, as, like as, just as, even as ; __1. with a demonstrative, like οὕτως, expressed or understood : οὕτως . . . ὡς, Mrk.4:26 , 1Co.3:15 , Eph.5:28 , Jas.2:12 , al.; ὡς . . . οὕτως, Act.8:32 , 1Co.7:17 , al.; elliptically (sc. οὕτως, οὕτω), with nom., Mat.6:29 , al.; with accusative, Mat.19:19 , Mrk.12:31 , al.; with prep., Mat.26:55 , Mrk.14:48 , Luk.22:52 , Jhn.7:10 , al.; with verb., Jhn.15:6 , 2Co.3:1 , Eph.2:3 , ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G5613') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (17185, 'sense:G6063:primary', 8099, 18457, NULL, 'primary', 1, 'to know', '1. to know , εὖ οἶδα I know well; εὖ ἴσθι be assured : often with accusative rei, νοήματα οἶδε, μήδεα οἶδε he is versed in counsels, (Homer); with neut. Adjs., πεπνυμένα, φίλα, ἀθεμίστια εἰδώς (Homer); also with genitive , τόξων εὖ εἰδώς cunning in the use of the bow; οἰωνῶν σάφα εἰδώς (Odyssey by Homer): —; χάριν εἰδέναι τινί to acknowledge a debt to another, thank him , (Iliad by Homer), etc.:—;the Imperat. in protestations, ἴστω Ζεὺς αὐτός be Zeus my witness , (Iliad by Homer); doric ἴττω Ζεύ', NULL, '{}'::text[], 'STEPBible TBESG / Abbott-Smith / Middle Liddell (CC BY 4.0)', 1, 4, 'TBESG:G6063') ON CONFLICT DO NOTHING;
