INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22250, 'sense:G0032H:sub', 2101, 12732, 11244, 'sub:G0032H', 2, 'angel: messenger', 'ἄγγελος , -ου, ὁ, [in LXX chiefly for מַלְאָךְ ;] __1. a messenger , one sent : Mat.11:10 , Jas.22:25 . __2. As in LXX, in the special sense of angel , a spiritual, heavenly being, attendant upon God and employed as his messenger to men, to make known his purposes, as Luk.1:11 , or to execute them, as Mat.4:6. The ἄ. in Rev.1:20-2:1 , al., is variously understood as __(1) a messenger or delegate, __(2) a bishop or ruler, __(3) a guardian angel, __(4) the prevailing spirit of each church, i.e. th', 'STEP disambiguated sub-sense (G0032H = a Meaning of G0032G)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G0032H') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22260, 'sense:G0906H:sub', 3035, 13628, 12179, 'sub:G0906H', 2, 'to throw: put', 'βάλλω , [in LXX for נפל, שׂום, ידד, etc. ;] prop., of a weapon or missile; then generally, of things and persons, lit. and metaphorically, to throw, cast, put, place : with accusative, before εἰς, Mat.4:18 , and frequently ἐπί, Mat.10:34; κάτω, Mat.4:6; ἔξω, Mat.5:13; ἀπό, Mat.5:29; ἐκ, Mrk.12:44; δρέπανον, Rev.14:19; μάχαιραν, Mat.10:34; κλῆρον, Mat.27:35; of fluids, to pour : Mat.9:17 , Jhn.13:5 ; pass., to be laid, to lie ill : Mat.9:2; ἐβλήθη (timeless aor., M, Pr. , 134), Jhn.15:6; intrans.', 'STEP disambiguated sub-sense (G0906H = a Meaning of G0906G)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G0906H') ON CONFLICT DO NOTHING;
