INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22267, 'sense:G1093G:sub', 3243, 13829, 12392, 'sub:G1093G', 2, 'earth: planet', 'γῆ , γῆς, ἡ, [in LXX for אֲדָמָה ,אֶרֶץ, etc. ;] __1. the earth, world : Luk.21:35 , Act.1:8 , Heb.11:13 , Rev.3:10 , al.; opposite to οὐρανός, Mat.5:18 11:25 , Mrk.13:27 , al. __2. land ; __(a) opposite to sea or water: Mrk.4:1 , Luk.5:3 , Jhn.6:21 , al.; __(b) as subject to cultivation : Mat.13:5 , Mrk.4:8 , Luk.13:7 , Heb.6:7 , al.; __(with) the ground : Mat.10:29 , Mrk.8:6 , Luk.24:5 , Jhn.8:6 , al.; __(d) a region, country : Luk.4:25 , Rom.9:28 , Jas.5:17 ; γῆ Ἰσραήλ, Mat.2:20, 21 ; Χαλδαίω', 'STEP disambiguated sub-sense (G1093G = a Meaning of G1093I)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G1093G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22268, 'sense:G1093H:sub', 3243, 13830, 12392, 'sub:G1093H', 3, 'earth: country', 'γῆ , γῆς, ἡ, [in LXX for אֲדָמָה ,אֶרֶץ, etc. ;] __1. the earth, world : Luk.21:35 , Act.1:8 , Heb.11:13 , Rev.3:10 , al.; opposite to οὐρανός, Mat.5:18 11:25 , Mrk.13:27 , al. __2. land ; __(a) opposite to sea or water: Mrk.4:1 , Luk.5:3 , Jhn.6:21 , al.; __(b) as subject to cultivation : Mat.13:5 , Mrk.4:8 , Luk.13:7 , Heb.6:7 , al.; __(with) the ground : Mat.10:29 , Mrk.8:6 , Luk.24:5 , Jhn.8:6 , al.; __(d) a region, country : Luk.4:25 , Rom.9:28 , Jas.5:17 ; γῆ Ἰσραήλ, Mat.2:20, 21 ; Χαλδαίω', 'STEP disambiguated sub-sense (G1093H = a Meaning of G1093I)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G1093H') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22269, 'sense:G20196:sub', 3248, 22441, 12397, 'sub:G20196', 2, 'be born', 'γίγνομαι , see: γίνομαι. γίνομαι , Ion. and κοινή for Att. γίγν- (M. Pr. , 47; Bl., §6, 8 Mayser, 166 f.), [in LXX chiefly for היה ;] __1. of persons, things occurrences, to come into being, be born, arise, come on : Jhn.1:15 8:58 , 1Co.15:37 ; a first appearance in public, Mrk.1:4 , Jhn.1:6 , al.; before ἐκ (of birth), Rom.1:3 , Gal.4:4 ; διά, Jhn.1:3; βροντή, Jhn.12:29; σεισμός, Rev.6:12; γογγυσμός, Act.6:1; χαρά, Act.8:8 , many other similar exx.; ἡμέρα, Luk.22:66 , al.; ὀψέ, Mrk.11:19; πρωΐα', 'STEP disambiguated sub-sense (G20196 = a Meaning of G1096)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G20196') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22273, 'sense:G1487H:sub', 3661, 14227, 12806, 'sub:G1487H', 2, 'if: not', 'εἰ , conjunctive particle , used in conditions and in indirect questions. __I. Conditional, if ; __1. with indic, expressing a general assumption; __(a) pres.: before indic, pres., Mat.11:14 , Rom.8:25 , al.; before imperat., Mrk.4:23 9:22 , Jhn.15:18 , 1Co.7:9 , al.; before fut. indic., Luk.16:31 , Rom.8:11 , al.; before pf. or aor., with negation in apodosis, Mat.12:26 , Rom.4:14 , al.; similarly, before impf., Luk.17:6 , Jhn.8:39 ; before quæst., Mat.6:23 , Jhn.5:47 7:23 8:46 , 1Pe.2:20 ; __(', 'STEP disambiguated sub-sense (G1487H = a Meaning of G1487G)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G1487H') ON CONFLICT DO NOTHING;
