INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22279, 'sense:G1492G:sub', 3666, 14237, 12810, 'sub:G1492G', 2, 'to perceive: understand', 'οἶδα , (from same root as εἶδον, which see), [in LXX chiefly for ידע ;] pf. with present meaning (plpf. as impf.; on irregular tense-forms, see App.), to have seen or perceived , hence, to know, have knowledge of : with accusative of thing(s), Mat.25:13 , Mrk.10:19 , Jhn.10:4 , Rom.7:7 , al.; with accusative of person(s), Mat.26:72 , Jhn.1:31 , Act.3:16 , al.; τ. θεόν, 1Th.4:5 , Tit.1:16 , al.; with accusative and inf., Luk.4:41 , al.; before ὅτι, Mat.9:6 , Luk.20:21 , Jhn.3:2 , Rom.2:2 11:2 , a', 'STEP disambiguated sub-sense (G1492G = a Meaning of G1492H)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G1492G') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22280, 'sense:G1492I:sub', 3666, 14239, 12810, 'sub:G1492I', 3, 'to perceive: know', 'οἶδα , (from same root as εἶδον, which see), [in LXX chiefly for ידע ;] pf. with present meaning (plpf. as impf.; on irregular tense-forms, see App.), to have seen or perceived , hence, to know, have knowledge of : with accusative of thing(s), Mat.25:13 , Mrk.10:19 , Jhn.10:4 , Rom.7:7 , al.; with accusative of person(s), Mat.26:72 , Jhn.1:31 , Act.3:16 , al.; τ. θεόν, 1Th.4:5 , Tit.1:16 , al.; with accusative and inf., Luk.4:41 , al.; before ὅτι, Mat.9:6 , Luk.20:21 , Jhn.3:2 , Rom.2:2 11:2 , a', 'STEP disambiguated sub-sense (G1492I = a Meaning of G1492H)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G1492I') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22281, 'sense:G3700:sub', 3666, 16423, 12810, 'sub:G3700', 4, 'to appear', 'ὀπτάνω [in LXX: 3Ki.8:8 (רָאָה ni.), Tob.12:19 * ;] late present as from ὤφθην (= ὁράω); mid., ὀπτάνομαι, to allow oneself to be seen, to appear. with dative, Act.1:3. (For exx. from π., see Deiss., LAE , 79, 2526; MM, ii, xviii.) † (AS)', 'STEP disambiguated sub-sense (G3700 = a Meaning of G1492H)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G3700') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22282, 'sense:G3708G:sub', 3666, 16431, 12810, 'sub:G3708G', 5, 'to see: see', 'ὁράω , -ῶ, [in LXX chiefly for ראה, also for חזה, etc. ;] in "durative" sense (hence aor. act., εἶδον, pass., ὤφθην, fut., ὄψομαι, from different roots; see M, Pr. , 110f.), to see (in colloq. even the present is rare, its place being generally taken by θεωρέω, see BL, §24). __1. Of bodily vision, to see, perceive, behold : absol., Mrk.6:38 , al.; ἔρχου καὶ ἴδε, Jhn.1:46 , al.; before ὅτι, Mrk.2:16 , al.; with accusative, Mat.2:2 , Mrk.1:10 16:7 , Gal.1:19 , al.; θεόν, Jhn.1:18 , 1Jn.4:20 , al. ', 'STEP disambiguated sub-sense (G3708G = a Meaning of G1492H)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G3708G') ON CONFLICT DO NOTHING;
