INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22296, 'sense:G2962H:sub', 5286, 15765, 14416, 'sub:G2962H', 2, 'lord: master', 'κύριος , -α, -ον (also -ος, -ον), [in LXX (subst.) chiefly for יהוה, also for בַּעַל ,אָדוֹן, etc. ;] having power (κῦρος) or authority ; as subst., ὁ κ., lord, master ; __1. in general : with genitive of thing(s), Mat.9:38 20:8 , Mrk.12:9 13:35 , Luk.19:33 ; τ. σαββάτου, Mat.12:8 , Mrk.2:28 , Luk.6:5 ; with genitive of person(s), δούλου, etc., Mat.10:24 , Luk.14:21 , Act.16:16 , al.; absol, opposite to οἱ δοῦλοι, Eph.6:5 , 9 al.; of the Emperor (Deiss., LAE , 161), Act.25:26; θεοὶ πολλοὶ καὶ κ.', 'STEP disambiguated sub-sense (G2962H = a Meaning of G2962G)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G2962H') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22297, 'sense:G3004H:sub', 5329, 15810, 14459, 'sub:G3004H', 2, 'to say: call', 'λέγω , [in LXX very freq., chiefly for אמר; λέγει for נְאֻם, Gen.22:16 , al. ;] __1. in Hom., to pick out, gather, reckon, recount . __2. In Hdt. and Att., to say, speak, affirm, declare : absol., Act.13:15, 24:10 ; before orat. dir., Mat.9:34 , Mrk.3:11 , Jhn.1:29 , al.; before ὅτι recit., Mrk.3:21 , Luk.1:24 , Jhn.6:14 , al.; accusative and inf., Luk.11:18 , Jhn.12:29 , al.; after another verb of speaking, προσφωνεῖν κ. λέγειν, Mat.11:17 , al.; ἀπεκρίθη (ἐλάλησεν) λέγων (καὶ λέγει; Dalman, Wor', 'STEP disambiguated sub-sense (G3004H = a Meaning of G3004G)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G3004H') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22311, 'sense:G4245H:sub', 6556, 16982, 15666, 'sub:G4245H', 2, 'elder: old', 'πρέσβυς , -εως, ὁ poët. form of πρεσβύτης (which see), [in LXX (= πρεσβευτής, an ambassador): Num.21:20 (21), al. (מֲלְאָךְ), Isa.13:8 57:9 (צִיר), 1Ma.9:70 , al. ;] an old man. Compar., πρεσβύτερος, -α, -ον, [in LXX chiefly for זָקֵן ;] __1. of age, elder : ὁ νἱὸς ὁ π., Luk.15:25; as subst., opposite to νεανίσκοι, Act.2:17; to νεώτερος, 1Ti.5:1-2; of the religious leaders of the past, Mat.15:2 , Mrk.7:3 , 5, Heb.11:2 (= οἱ πατέρες, Heb.1:1 ). __2. Of dignity, rank or office (as found in π. and ', 'STEP disambiguated sub-sense (G4245H = a Meaning of G4245G)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G4245H') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22315, 'sense:G4690H:sub', 7048, 17445, 16150, 'sub:G4690H', 2, 'seed(s)', 'σπέρμα , -τος, τό (σπείρω) [in LXX chiefly for זֶרַע ;] seed ; __(a) of plants : Mat.13:24, 27 13:37-38 , 2Co.9:10 ; pl., Mat.13:32 , Mrk.4:31 , 1Co.15:33 ; metaphorically, of an escaping remnant (שָׂרִיד, Isa.1:9; cf. Wis.14:6; Plat., Tim., 23c; FlJ, Ant. , xi, 5, 3), Rom.9:29; __(b) of men (as γονή; Lat. semen genitale; so in cl.; cf. in LXX, Lev.15:16 , al.): Heb.11:11 ; metaphorically, of the divine influence, 1Jn.3:9; by meton. (as frequently in poets), seed, offspring, posterity : Mat.22:2', 'STEP disambiguated sub-sense (G4690H = a Meaning of G4690G)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G4690H') ON CONFLICT DO NOTHING;
