INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22323, 'sense:G5259H:sub', 7663, 18022, 16756, 'sub:G5259H', 2, 'by/under: under', 'ὑπό (before smooth breathing ὑπ᾽, Mat.8:9 b, Luk.7:8 b; before rough breathing ὑφ᾽, Rom.3:9; on the neglect of elision in Mt, Lk, ll. witha, Gal.3:22 , see WH, App. , 146; Tdf., Pr. , iv), prep. with genitive, dative (not in NT), accusative __I. C. genitive, primarily of place, under , hence, metaphorically, of the efficient cause, by : after passive verbs, with genitive of person(s), Mat.1:22 , Mrk.1:5 , Luk.2:18 , Jhn.14:21 , Act.4:11 , 1Co.1:11 , Heb.3:4 , al.; with genitive of thing(s), Mat.', 'STEP disambiguated sub-sense (G5259H = a Meaning of G5259G)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G5259H') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (22327, 'sense:G5456G:sub', 7874, 18228, 16963, 'sub:G5456G', 2, 'voice/sound: voice', 'φωνή , -ῆς, ἡ, [in LXX chiefly and very frequently for קוֹל ;] a voice ; __(a) prop., of persons, Mat.2:18 (LXX), al.; φ. αἴρειν (ἐπαίρειν), Luk.17:13 , Act.2:14 , al.; φ. μεγάλῃ εἰπεῖν (λέγειν, φωνεῖν, etc.), Luk.8:28 , Act.7:57 , Rev.5:12 , al.; γίνεται (ἔρχεται) φ. ἐκ τ. οὐρανῶν (ἐξ οὐρανοῦ), Mrk.1:11 , Luk.3:22 , Jhn.12:28 , al. (cf. DCG , ii, 810a; Dalman, Words , 204f.); ἀκούειν φωνήν (-ῆς; see: ἀκούω), Act.9:4 , 7 al.; φ. βοῶντος, Mat.3:3 , Mrk.1:3 , Luk.3:4 , Jhn.1:23 " (LXX) ; τ. θεοῦ, ', 'STEP disambiguated sub-sense (G5456G = a Meaning of G5456H)', '{}'::text[], 'STEPBible TBESG Sub-sense (CC BY 4.0)', 1, 4, 'TBESG:G5456G') ON CONFLICT DO NOTHING;
