INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (25203, 'sense:G3956:as:1:3', 6247, 16681, 15364, 'AS.1', 2, 'with subst. anarth., all, every, of every kind', 'with subst. anarth., all, every, of every kind : Mat.3:10 4:23 , Mrk.9:49 , Luk.4:37 , Jhn.2:1 o, Act.27:20 , Rom.7:8 , Rev.18:17 , al. mult.; pl., all , Act.22:15 , Rom.5:12 , Heb.1:6 , al.; of the highest degree, π. ἐξουσία (προθυμία, χαρά), Mat.28:18 , Act.17:11 , Phi 2:29 , al.; also the whole (though in this sense more frequently with art.), Mat.2:3 , Act.2:36 , Rom.11:26 .', NULL, ARRAY['Mat.3:10','Mrk.9:49','Luk.4:37','Jhn.2:1','Act.27:20','Rom.7:8','Rev.18:17','Act.22:15','Rom.5:12','Heb.1:6','Mat.28:18','Act.17:11','Mat.2:3','Act.2:36','Rom.11:26']::text[], 'Abbott-Smith Manual Greek Lexicon of the NT via STEP TBESG (CC BY 4.0)', 1, 4, 'TBESG:G3956#1') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (25281, 'sense:G4098:as:1:2', 6395, 16829, 15507, 'AS.1', 2, 'of descent, to fall, fall down or from', 'of descent, to fall, fall down or from : before ἐπί, with accusative loc., Mat.10:29 , al.; εἰς, Mat.15:14 , al.; ἐς μέσῳ, with genitive, Luk.8:7; παρὰ τ. ὁδόν, Mat.13:4 , Mrk.4:4 , Luk.8:5 ; before ἀπό, Mat.15:27 , al.; ἐκ, Mrk.13:25 , Luk.10:18 , Rev.8:10 9:1 . Metaphorical: ὁ ἥλιος, before ἐπί, Rev.7:16; ἀχλὺς κ. σκότος, Act.13:11; ὁ κλῆρος, Act.1:26; ὑπὸ κρίσιν, Jas.5:12.', NULL, ARRAY['Mat.10:29','Mat.15:14','Luk.8:7','Mat.13:4','Mrk.4:4','Luk.8:5','Mat.15:27','Mrk.13:25','Luk.10:18','Rev.8:10','Rev.7:16','Act.13:11','Act.1:26','Jas.5:12']::text[], 'Abbott-Smith Manual Greek Lexicon of the NT via STEP TBESG (CC BY 4.0)', 1, 4, 'TBESG:G4098#1') ON CONFLICT DO NOTHING;
