INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (25537, 'sense:G4459:as:1:2', 6781, 17199, 15891, 'AS.1', 2, 'prop., in direct questions, how?', 'prop., in direct questions, how? : with indic., Mat.12:29 , Mrk.3:23 , Luk.11:18 , Jhn.3:4 , al.; καὶ π., Mrk.4:13 , Luk.20:44 ; π. οὖν, Mat.12:26; π. οὐ, Mat.16:11 , Luk.12:56 ; in deliberative questions (cf. Bl., §64, 6), with subjc., Mat.23:33 26:54 ; π. οὖν, Rom.10:14; π. δέ, Rom.10:14, 15 ; before ἄν, with optative, Act.8:31.', NULL, ARRAY['Mat.12:29','Mrk.3:23','Luk.11:18','Jhn.3:4','Mrk.4:13','Luk.20:44','Mat.12:26','Mat.16:11','Luk.12:56','Mat.23:33','Rom.10:14','Rom.10:14','Act.8:31']::text[], 'Abbott-Smith Manual Greek Lexicon of the NT via STEP TBESG (CC BY 4.0)', 1, 4, 'TBESG:G4459#1') ON CONFLICT DO NOTHING;
