INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (25628, 'sense:G4621:as:1:2', 6970, 17374, 16079, 'AS.1', 2, 'corn, grain', 'corn, grain : Act.7:12 (but see 131., § 9, 1).', NULL, ARRAY['Act.7:12']::text[], 'Abbott-Smith Manual Greek Lexicon of the NT via STEP TBESG (CC BY 4.0)', 1, 4, 'TBESG:G4621#1') ON CONFLICT DO NOTHING;
