INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (25893, 'sense:G5101:as:1:3', 7494, 17863, 16590, 'AS.1', 2, '1. masc., fem.', '1. masc., fem.: τίς; who, what? , Mat.3:7 26:68 ; Mrk.11:28 , Luk.9:9 , al. mult.; with genitive partit., Act.7:52 , Heb.1:5 , al; before ἐκ (= genitive partit.), Mat.6:27 , Luk.14:28 , Jhn.8:46 ; = ποῖος, Mrk.4:41 6:2 , Luk.19:3 , Act.17:19 , al.; = πότερος (M, Pr. , 77), Mat.21:31 27:17', NULL, ARRAY['Mat.3:7','Mrk.11:28','Luk.9:9','Act.7:52','Heb.1:5','Mat.6:27','Luk.14:28','Jhn.8:46','Mrk.4:41','Luk.19:3','Act.17:19','Mat.21:31']::text[], 'Abbott-Smith Manual Greek Lexicon of the NT via STEP TBESG (CC BY 4.0)', 1, 4, 'TBESG:G5101#1') ON CONFLICT DO NOTHING;
INSERT INTO public.lexical_senses ("id", "sense_key", "lemma_id", "lexeme_id", "parent_sense_id", "sense_code", "sense_order", "short_gloss", "definition_text", "usage_note", "scripture_refs", "source_attribution", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (26001, 'sense:G5342:as:1:2', 7748, 18107, 16842, 'AS.1', 2, 'to bear, carry', 'to bear, carry : with accusative, Luk.23:26 24:1 , Jhn.19:39 , Heb.1:3 (see Westc., in l); pass., Act.2:2 27:15, 17 Heb.6:1 , 2Pe.1:17-18 ; of the mind, 2Pe.1:21.', NULL, ARRAY['Luk.23:26','Jhn.19:39','Heb.1:3','Act.2:2','Heb.6:1']::text[], 'Abbott-Smith Manual Greek Lexicon of the NT via STEP TBESG (CC BY 4.0)', 1, 4, 'TBESG:G5342#1') ON CONFLICT DO NOTHING;
