INSERT INTO public.concepts ("id", "concept_key", "title", "concept_kind", "summary", "primary_strongs", "distinct_from_note", "external_entity_type", "epistemic_layer", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (1, 'WELL', 'Well / Water Source (בְּאֵר / πηγή)', 'natural_feature', 'A dug water well or spring in the ancient Near East, serving as a pastoral gathering point and recurring Pentateuchal narrative setting.', ARRAY['H875','H5869','G4077','G5421']::text[], 'The narrative betrothal motif at a well is a literary pattern across episodes, not the lexical definition of H875 (be.er).', 'literary_motif', 'reviewed_research', 3, 10, 'curated-motifs-v1:WELL') ON CONFLICT DO NOTHING;
INSERT INTO public.concepts ("id", "concept_key", "title", "concept_kind", "summary", "primary_strongs", "distinct_from_note", "external_entity_type", "epistemic_layer", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (2, 'MARRIAGE', 'Betrothal & Marriage (לָקַח לְאִשָּׁה / γάμος)', 'social_institution', 'Covenantal marriage and betrothal narratives in Scripture, often expressed through multi-word Hebrew idioms ("take as a wife") rather than a single noun.', ARRAY['H802','H3947','H2859','G1062']::text[], 'Requires narrative-unit span tracking because the encounter at a well and the marriage consummation occur many verses apart.', 'literary_motif', 'reviewed_research', 3, 10, 'curated-motifs-v1:MARRIAGE') ON CONFLICT DO NOTHING;
INSERT INTO public.concepts ("id", "concept_key", "title", "concept_kind", "summary", "primary_strongs", "distinct_from_note", "external_entity_type", "epistemic_layer", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (3, 'LAMPSTAND', 'Seven-Branched Lampstand / Menorah (מְנוֹרָה / λυχνία)', 'theological_symbol', 'The golden seven-branched lampstand of the Tabernacle (Exod 25:31-40) and Zechariah''s vision (Zech 4:2), and the seven golden lampstands of Revelation 1:12-20.', ARRAY['H4501','G3087']::text[], 'Must be kept lexically distinct from individual lamps/torches (H5216 ner, G2985 lampas). In Rev 1:20, the seven lampstands (G3087) are explicitly identified as the seven churches.', 'literary_motif', 'reviewed_research', 3, 10, 'curated-motifs-v1:LAMPSTAND') ON CONFLICT DO NOTHING;
INSERT INTO public.concepts ("id", "concept_key", "title", "concept_kind", "summary", "primary_strongs", "distinct_from_note", "external_entity_type", "epistemic_layer", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (4, 'LAMP_TORCH', 'Lamp / Torch of Fire (נֵר / λαμπάς)', 'object', 'Individual oil lamps or blazing torches, including the seven lamps on Zechariah''s menorah (Zech 4:2) and the seven torches of fire burning before God''s throne (Rev 4:5).', ARRAY['H5216','G2985','G3088']::text[], 'Distinct from the lampstand support (H4501 / G3087).', 'literary_motif', 'reviewed_research', 3, 10, 'curated-motifs-v1:LAMP_TORCH') ON CONFLICT DO NOTHING;
INSERT INTO public.concepts ("id", "concept_key", "title", "concept_kind", "summary", "primary_strongs", "distinct_from_note", "external_entity_type", "epistemic_layer", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (5, 'SEVEN_SPIRITS_OF_GOD', 'Seven Spirits of God (ἑπτὰ πνεύματα τοῦ θεοῦ)', 'theological_symbol', 'Johannine apocalyptic title in Revelation 1:4, 3:1, 4:5, and 5:6, linked textually in Rev 4:5 to seven burning lamps/torches and in Rev 5:6 to seven horns and seven eyes (alluding to Zech 4:2-10).', ARRAY['G4151','G2033','H7307','H5869']::text[], 'Sharing the number seven (H7651 / G2033) alone never establishes an equivalence; links require explicit textual or prophetic-allusion evidence.', 'literary_motif', 'reviewed_research', 3, 10, 'curated-motifs-v1:SEVEN_SPIRITS_OF_GOD') ON CONFLICT DO NOTHING;
INSERT INTO public.concepts ("id", "concept_key", "title", "concept_kind", "summary", "primary_strongs", "distinct_from_note", "external_entity_type", "epistemic_layer", "source_release_id", "source_edition_id", "source_record_id") OVERRIDING SYSTEM VALUE VALUES (6, 'PLACE:openbible:a6d9af3', 'Haran', 'object', 'Identified as Harran (settlement). Supported by OpenBible geocoding synthesis (score 922).', ARRAY['H2771B']::text[], 'External geographical/archaeological identification from OpenBible/Pleiades/TIPNR; external factual data is distinct from biblical theological interpretation.', 'biblical_place', 'external_factual', 5, 8, 'places:openbible:a6d9af3') ON CONFLICT DO NOTHING;
